test "artifact repair shard run request preserves repair target" {
    const shard_req = artifactRepairRunRequestForShard(.{
        .target = .index,
        .artifact_kind = .embedding,
        .index_name = "semantic",
        .limit = 10,
        .cursor = "idx_b",
        .force = true,
        .repair_job_id = 42,
        .repair_attempt_id = 7,
        .repair_cancel_base_uri = "http://node-a",
    }, 2, "idx_c");

    try std.testing.expectEqual(db_mod.types.RepairTarget.index, shard_req.target);
    try std.testing.expectEqual(db_mod.types.ArtifactRepairKind.embedding, shard_req.artifact_kind.?);
    try std.testing.expectEqualStrings("semantic", shard_req.index_name.?);
    try std.testing.expectEqual(@as(u32, 2), shard_req.limit);
    try std.testing.expectEqualStrings("idx_c", shard_req.cursor.?);
    try std.testing.expect(shard_req.force);
    try std.testing.expectEqual(@as(u64, 42), shard_req.repair_job_id.?);
    try std.testing.expectEqual(@as(u64, 7), shard_req.repair_attempt_id.?);
    try std.testing.expectEqualStrings("http://node-a", shard_req.repair_cancel_base_uri.?);
}

fn cloneArtifactRepairIssueAlloc(alloc: std.mem.Allocator, issue: db_mod.types.ArtifactRepairIssue) !db_mod.types.ArtifactRepairIssue {
    var out = db_mod.types.ArtifactRepairIssue{
        .artifact_kind = issue.artifact_kind,
        .chunk_id = issue.chunk_id,
        .repairable = issue.repairable,
        .sequence = issue.sequence,
        .reason = issue.reason,
        .attempts = issue.attempts,
        .first_seen_ns = issue.first_seen_ns,
        .last_seen_ns = issue.last_seen_ns,
    };
    errdefer out.deinit(alloc);
    out.index_name = try alloc.dupe(u8, issue.index_name);
    out.doc_key = try alloc.dupe(u8, issue.doc_key);
    out.parent_doc_key = try alloc.dupe(u8, issue.parent_doc_key);
    out.unit_id = try alloc.dupe(u8, issue.unit_id);
    out.source_artifact_name = try alloc.dupe(u8, issue.source_artifact_name);
    out.artifact_name = try alloc.dupe(u8, issue.artifact_name);
    out.artifact_key = try alloc.dupe(u8, issue.artifact_key);
    out.unsupported_reason = try alloc.dupe(u8, issue.unsupported_reason);
    out.last_error = try alloc.dupe(u8, issue.last_error);
    return out;
}

fn parseArtifactRepairListResultAlloc(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.ArtifactRepairListResult {
    var parsed = try std.json.parseFromSlice(db_mod.types.ArtifactRepairListResult, alloc, body, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();

    var issues = try alloc.alloc(db_mod.types.ArtifactRepairIssue, parsed.value.issues.len);
    var initialized_issues: usize = 0;
    errdefer {
        for (issues[0..initialized_issues]) |*issue| issue.deinit(alloc);
        if (issues.len > 0) alloc.free(issues);
    }
    for (parsed.value.issues, issues) |issue, *out| {
        out.* = try cloneArtifactRepairIssueAlloc(alloc, issue);
        initialized_issues += 1;
    }

    return .{
        .issues = issues,
        .limit = parsed.value.limit,
        .scanned = parsed.value.scanned,
        .groups_scanned = parsed.value.groups_scanned,
        .next_cursor = if (parsed.value.next_cursor) |cursor| try alloc.dupe(u8, cursor) else null,
        .has_more = parsed.value.has_more,
    };
}

fn parseArtifactRepairResultAlloc(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.ArtifactRepairResult {
    var parsed = try std.json.parseFromSlice(db_mod.types.ArtifactRepairResult, alloc, body, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();

    return .{
        .scanned = parsed.value.scanned,
        .groups_scanned = parsed.value.groups_scanned,
        .reprocessed = parsed.value.reprocessed,
        .repaired = parsed.value.repaired,
        .missing_source_docs = parsed.value.missing_source_docs,
        .failed = parsed.value.failed,
        .unsupported = parsed.value.unsupported,
        .unresolved = parsed.value.unresolved,
        .in_progress = parsed.value.in_progress,
        .indexes_rebuilt = parsed.value.indexes_rebuilt,
        .indexes_degraded = parsed.value.indexes_degraded,
        .limit = parsed.value.limit,
        .next_cursor = if (parsed.value.next_cursor) |cursor| try alloc.dupe(u8, cursor) else null,
        .has_more = parsed.value.has_more,
        .debt_remaining = parsed.value.debt_remaining,
    };
}

fn parseDocumentArtifactTableReprocessResultAlloc(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.DocumentArtifactTableReprocessResult {
    const RemoteFailure = struct {
        key: []const u8,
        error_code: []const u8,
    };
    const RemoteShardCursor = struct {
        group_id: ?u64 = null,
        next_key: []const u8,
        scanned: usize = 0,
        reprocessed: usize = 0,
        skipped: usize = 0,
        failed: usize = 0,
        limit: u32 = 0,
    };
    const RemoteResult = struct {
        scanned: usize = 0,
        reprocessed: usize = 0,
        skipped: usize = 0,
        failed: usize = 0,
        limit: u32 = 0,
        next_key: ?[]const u8 = null,
        failures: []const RemoteFailure = &.{},
        shard_cursors: []const RemoteShardCursor = &.{},
    };

    var parsed = try std.json.parseFromSlice(RemoteResult, alloc, body, .{});
    defer parsed.deinit();

    var failures = try alloc.alloc(db_mod.types.DocumentArtifactReprocessFailure, parsed.value.failures.len);
    var initialized: usize = 0;
    errdefer {
        for (failures[0..initialized]) |*failure| failure.deinit(alloc);
        if (failures.len > 0) alloc.free(failures);
    }
    for (parsed.value.failures, failures) |remote, *out| {
        out.* = .{
            .key = try alloc.dupe(u8, remote.key),
            .error_code = try alloc.dupe(u8, remote.error_code),
        };
        initialized += 1;
    }
    var shard_cursors = try alloc.alloc(db_mod.types.DocumentArtifactReprocessShardCursor, parsed.value.shard_cursors.len);
    var initialized_cursors: usize = 0;
    errdefer {
        for (shard_cursors[0..initialized_cursors]) |*cursor| cursor.deinit(alloc);
        if (shard_cursors.len > 0) alloc.free(shard_cursors);
    }
    for (parsed.value.shard_cursors, shard_cursors) |remote, *out| {
        out.* = .{
            .group_id = remote.group_id,
            .next_key = try alloc.dupe(u8, remote.next_key),
            .scanned = remote.scanned,
            .reprocessed = remote.reprocessed,
            .skipped = remote.skipped,
            .failed = remote.failed,
            .limit = remote.limit,
        };
        initialized_cursors += 1;
    }

    return .{
        .scanned = parsed.value.scanned,
        .reprocessed = parsed.value.reprocessed,
        .skipped = parsed.value.skipped,
        .failed = parsed.value.failed,
        .limit = parsed.value.limit,
        .next_key = if (parsed.value.next_key) |value| try alloc.dupe(u8, value) else null,
        .failures = failures,
        .shard_cursors = shard_cursors,
    };
}

const DroppedTableDeleteWork = struct {
    path: []u8,

    fn deletePath(path: []const u8, log_failure: bool) !void {
        var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer io_impl.deinit();
        runTestBeforeDropTableDeleteHook();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch |err| {
            if (!log_failure) return err;
            std.log.warn("background dropped-table delete failed path={s} err={s}", .{
                path,
                @errorName(err),
            });
        };
    }

    fn run(ptr: *anyopaque) !void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        try deletePath(self.path, true);
    }

    fn deinit(ptr: *anyopaque) void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        std.heap.page_allocator.free(self.path);
        std.heap.page_allocator.destroy(self);
    }
};

fn droppedTableTrashDirPath(alloc: std.mem.Allocator, replica_root_dir: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}/{s}", .{ replica_root_dir, dropped_table_trash_dir_name });
}

fn droppedTableTrashPath(
    alloc: std.mem.Allocator,
    replica_root_dir: []const u8,
    table_name: []const u8,
    group_id: u64,
) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}/{s}/table-{s}-group-{d}-{d}", .{
        replica_root_dir,
        dropped_table_trash_dir_name,
        table_name,
        group_id,
        platform_time.monotonicNs(),
    });
}

fn moveDroppedGroupPathToTrash(
    alloc: std.mem.Allocator,
    replica_root_dir: []const u8,
    table_name: []const u8,
    group_id: u64,
) !?[]u8 {
    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
    defer alloc.free(path);

    const trash_dir_path = try droppedTableTrashDirPath(alloc, replica_root_dir);
    defer alloc.free(trash_dir_path);
    const trash_path = try droppedTableTrashPath(alloc, replica_root_dir, table_name, group_id);
    errdefer alloc.free(trash_path);

    var io_impl = std.Io.Threaded.init(alloc, .{});
    defer io_impl.deinit();
    try fs_paths.createDirPathPortable(io_impl.io(), trash_dir_path);
    std.Io.Dir.rename(std.Io.Dir.cwd(), path, std.Io.Dir.cwd(), trash_path, io_impl.io()) catch |err| switch (err) {
        error.FileNotFound => return null,
        else => return err,
    };
    return trash_path;
}

fn deleteGroupPathIfPresent(
    alloc: std.mem.Allocator,
    replica_root_dir: []const u8,
    group_id: u64,
) !void {
    const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, replica_root_dir, group_id);
    defer alloc.free(path);

    var io_impl = std.Io.Threaded.init(alloc, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().access(io_impl.io(), path, .{}) catch |err| switch (err) {
        error.FileNotFound => return,
        else => return err,
    };
    try std.Io.Dir.cwd().deleteTree(io_impl.io(), path);
}

pub const ProvisionedTableWriteCache = struct {
    const TableEvictionHook = struct {
        ptr: *anyopaque,
        on_evict: *const fn (ptr: *anyopaque, cache: *ProvisionedTableWriteCache, table_name: []const u8) void,

        fn notify(self: @This(), cache: *ProvisionedTableWriteCache, table_name: []const u8) void {
            self.on_evict(self.ptr, cache, table_name);
        }
    };

    alloc: std.mem.Allocator,
    lsm_cache: ?*lsm_backend.Cache = null,
    hbc_cache: ?*hbc_mod.Cache = null,
    resource_manager: ?*resource_manager_mod.ResourceManager = null,
    backend_runtime: ?*db_mod.background_runtime.BackendRuntime = null,
    antfly_provider: ?managed_embedder.AntflyProvider = null,
    inference_api_url: ?[]const u8 = null,
    secret_store: ?*common_secrets.FileStore = null,
    remote_content: ?*const scraping.RemoteContentConfig = null,
    /// Cross-shard entity-resolution candidate source applied to every managed
    /// DB this cache opens (set after open; see `setResolutionCandidateSource`).
    resolution_candidate_source: ?db_mod.CandidateSource = null,
    /// Cross-shard entity sink for the promoter, applied to every managed DB
    /// this cache opens (set after open; see `setEntitySink`).
    entity_sink: ?db_mod.EntitySink = null,
    /// Source-group leadership predicate for promotion ownership. When set, each
    /// managed DB gets a group-specific `PromotionOwner` so only the local leader
    /// promotes resolution replay into cross-shard entity writes.
    promotion_leadership_source: ?PromotionLeadershipSource = null,
    /// Optional HA ownership gate applied when this cache opens managed writer
    /// DBs. Changing the gate retires live cached DBs so the next operation
    /// reopens with the correct primary/standby role and background runtimes.
    ha_write_gate: ?db_mod.HAWriteGate = null,
    /// Optional HA primary mirror applied when this cache opens managed writer
    /// DBs. Changing the mirror retires live cached DBs so already-open tables
    /// cannot silently continue without primary-side replication.
    ha_async_mirror: ?db_mod.HAAsyncEffectMirror = null,
    table_eviction_hook: ?TableEvictionHook = null,
    open_mutex: std.atomic.Mutex = .unlocked,
    entry_lifecycle_mutex: std.atomic.Mutex = .unlocked,
    hit_count: std.atomic.Value(u64) = .init(0),
    miss_count: std.atomic.Value(u64) = .init(0),
    entries: std.ArrayListUnmanaged(*Entry) = .empty,
    retired_entries: std.ArrayListUnmanaged(*Entry) = .empty,
    closing_entries: std.ArrayListUnmanaged(*Entry) = .empty,
    table_metadata: std.ArrayListUnmanaged(TableMetadata) = .empty,
    active_bulk_ingest_sessions: std.ArrayListUnmanaged(ActiveBulkIngestSession) = .empty,

    pub const CacheStats = struct {
        hit_count: u64 = 0,
        miss_count: u64 = 0,
    };

    pub const AutoBulkIngestStats = struct {
        cached_entries: u64 = 0,
        open_entries: u64 = 0,
        active_leases: u64 = 0,
        finish_requested_entries: u64 = 0,
        idle_expired_entries: u64 = 0,
        active_bulk_sessions: u64 = 0,
        total_ops: u64 = 0,
        oldest_idle_ns: u64 = 0,

        fn merge(self: *AutoBulkIngestStats, other: AutoBulkIngestStats) void {
            self.cached_entries += other.cached_entries;
            self.open_entries += other.open_entries;
            self.active_leases += other.active_leases;
            self.finish_requested_entries += other.finish_requested_entries;
            self.idle_expired_entries += other.idle_expired_entries;
            self.active_bulk_sessions += other.active_bulk_sessions;
            self.total_ops += other.total_ops;
            self.oldest_idle_ns = @max(self.oldest_idle_ns, other.oldest_idle_ns);
        }
    };

    pub const Diagnostics = struct {
        cached_entries: u64 = 0,
        retired_entries: u64 = 0,
        table_metadata_entries: u64 = 0,
        active_bulk_sessions: u64 = 0,
        active_leases: u64 = 0,
        retired_active_leases: u64 = 0,
        bulk_ingest_open_entries: u64 = 0,
        auto_bulk_ingest_open_entries: u64 = 0,
        auto_bulk_ingest_finish_requested_entries: u64 = 0,
        lsm_mutable_bytes: u64 = 0,
        lsm_immutable_bytes: u64 = 0,
        lsm_total_run_bytes: u64 = 0,
        lsm_wal_retained_bytes: u64 = 0,
        lsm_wal_retained_segments: u64 = 0,
        lsm_active_readers: u64 = 0,
        lsm_obsolete_paths: u64 = 0,
        lsm_bulk_ingest_current_scan_clone_active_bytes: u64 = 0,
    };

    pub const CachedDb = struct {
        cache: ?*ProvisionedTableWriteCache = null,
        entry: ?*Entry = null,
        db: *db_mod.DB,
        schema_json: ?[]const u8,
        owned_db: ?*db_mod.DB = null,

        pub fn deinit(self: *CachedDb, alloc: std.mem.Allocator) void {
            if (self.entry) |entry| {
                if (self.cache) |cache| cache.releaseEntry(entry);
                self.entry = null;
            }
            if (self.owned_db) |owned| {
                owned.close();
                alloc.destroy(owned);
            }
            self.* = undefined;
        }
    };

    const PreparedOpen = struct {
        indexes_json: ?[]u8 = null,
        schema_json: ?[]u8 = null,

        fn deinit(self: *PreparedOpen, alloc: std.mem.Allocator) void {
            if (self.indexes_json) |value| alloc.free(value);
            if (self.schema_json) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    const GetOrPrepareOpen = union(enum) {
        cached: CachedDb,
        prepared: PreparedOpen,
        pending_close,
    };

    const Entry = struct {
        group_id: u64,
        lsm_root_generation: u64,
        ha_write_gate_generation: ?u64 = null,
        table_name: []u8,
        promotion_owner_state: PromotionOwnerState = .{},
        db: db_mod.DB,
        schema_json: ?[]u8 = null,
        active_leases: usize = 0,
        retired: bool = false,
        close_queued: bool = false,
        allow_generation_adoption: bool = false,
        allow_active_generation_adoption: bool = false,
        bulk_ingest_session_open: bool = false,
        auto_bulk_ingest_session_open: bool = false,
        auto_bulk_ingest_ops: usize = 0,
        auto_bulk_ingest_started_ns: u64 = 0,
        auto_bulk_ingest_last_ns: u64 = 0,
        auto_bulk_ingest_finish_requested: bool = false,

        fn detachRuntimeHooks(self: *Entry) void {
            self.db.setQueryVisibilityHook(null);
            self.db.setResolutionCandidateSource(null);
            self.db.setEntitySink(null);
            self.db.setPromotionOwner(null);
            self.promotion_owner_state = .{};
        }

        fn deinit(self: *Entry, alloc: std.mem.Allocator) void {
            if (self.bulk_ingest_session_open) {
                if (self.auto_bulk_ingest_session_open) {
                    self.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(auto_bulk_ingest_finish_options) catch |err| {
                        std.log.warn("auto bulk ingest finish failed before cached db close table={s} err={s}", .{
                            self.table_name,
                            @errorName(err),
                        });
                        self.db.abortPrimaryStoreAutoBulkIngestSession();
                    };
                } else {
                    self.db.abortBulkIngestSession();
                }
                self.bulk_ingest_session_open = false;
                self.auto_bulk_ingest_session_open = false;
                self.auto_bulk_ingest_ops = 0;
                self.auto_bulk_ingest_started_ns = 0;
                self.auto_bulk_ingest_last_ns = 0;
                self.auto_bulk_ingest_finish_requested = false;
            }
            self.detachRuntimeHooks();
            // Read-side cache invalidation must not turn the first query after
            // a large weak-sync load into a full derived-index drain. DB.close()
            // tears down async workers and flushes owned storage; callers that
            // require full-index visibility must request it through sync_level
            // or the index status path before reading.
            const pending = self.db.pendingWorkStats();
            if (pending.enrichment.error_count == 0) {
                self.db.core.index_manager.syncAll(false) catch |err| {
                    std.log.warn("provisioned write cache sync failed before close: {}", .{err});
                };
            }
            self.db.close();
            alloc.free(self.table_name);
            if (self.schema_json) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    pub const PromotionLeadershipSource = struct {
        ptr: *anyopaque,
        vtable: *const VTable,

        pub const VTable = struct {
            is_local_leader: *const fn (ptr: *anyopaque, group_id: u64) bool,
        };

        pub fn isLocalLeader(self: PromotionLeadershipSource, group_id: u64) bool {
            return self.vtable.is_local_leader(self.ptr, group_id);
        }
    };

    const PromotionOwnerState = struct {
        group_id: u64 = 0,
        leadership_source: ?PromotionLeadershipSource = null,

        fn owner(self: *PromotionOwnerState) ?db_mod.PromotionOwner {
            if (self.leadership_source == null) return null;
            return .{ .ptr = self, .vtable = &owner_vtable };
        }

        const owner_vtable = db_mod.PromotionOwner.VTable{ .is_local_owner = isLocalOwner };

        fn isLocalOwner(ptr: *anyopaque) bool {
            const self: *PromotionOwnerState = @ptrCast(@alignCast(ptr));
            const source = self.leadership_source orelse return true;
            return source.isLocalLeader(self.group_id);
        }
    };

    fn applyRuntimeHooksToDb(self: *ProvisionedTableWriteCache, db: *db_mod.DB, group_id: u64, owner_state: ?*PromotionOwnerState) void {
        db.setResolutionCandidateSource(self.resolution_candidate_source);
        db.setEntitySink(self.entity_sink);
        if (owner_state) |state| {
            state.* = .{
                .group_id = group_id,
                .leadership_source = self.promotion_leadership_source,
            };
            db.setPromotionOwner(state.owner());
        } else {
            db.setPromotionOwner(null);
        }
    }

    fn entryHAWriteGateCurrent(self: *const ProvisionedTableWriteCache, entry: *const Entry) bool {
        return entry.ha_write_gate_generation == haWriteGateCurrentGeneration(self.ha_write_gate);
    }

    fn retireFailedOpenLocked(self: *ProvisionedTableWriteCache, cached: *CachedDb) void {
        const entry = cached.entry orelse {
            cached.deinit(self.alloc);
            return;
        };

        var i: usize = 0;
        while (i < self.entries.items.len) : (i += 1) {
            if (self.entries.items[i] != entry) continue;
            _ = self.entries.orderedRemove(i);
            break;
        }

        if (!entry.retired) self.retireEntryLocked(entry);
        cached.deinit(self.alloc);
    }

    fn retireCachedLeaseAfterMutationFailureLocked(self: *ProvisionedTableWriteCache, cached: *CachedDb) void {
        const entry = cached.entry orelse {
            cached.deinit(self.alloc);
            return;
        };

        var track_retirement = true;
        if (!entry.retired) self.reserveRetiredEntriesCapacityLocked(1) catch |err| {
            std.log.err("failed to reserve retired writer-cache entry after structural mutation failure: {}", .{err});
            track_retirement = false;
        };

        var i: usize = 0;
        while (i < self.entries.items.len) : (i += 1) {
            if (self.entries.items[i] != entry) continue;
            _ = self.entries.orderedRemove(i);
            break;
        }

        if (!entry.retired) {
            if (track_retirement) {
                self.retireEntryLocked(entry);
            } else {
                self.markEntryRetiredUntrackedLocked(entry);
            }
        }
        cached.deinit(self.alloc);
    }

    fn refreshRuntimeHooksLocked(self: *ProvisionedTableWriteCache) void {
        for (self.entries.items) |entry| {
            self.applyRuntimeHooksToDb(&entry.db, entry.group_id, &entry.promotion_owner_state);
        }
    }

    fn candidateSourcesEqual(a: ?db_mod.CandidateSource, b: ?db_mod.CandidateSource) bool {
        if (a == null or b == null) return a == null and b == null;
        return a.?.ptr == b.?.ptr and a.?.vtable == b.?.vtable;
    }

    fn entitySinksEqual(a: ?db_mod.EntitySink, b: ?db_mod.EntitySink) bool {
        if (a == null or b == null) return a == null and b == null;
        return a.?.ptr == b.?.ptr and a.?.vtable == b.?.vtable;
    }

    fn promotionLeadershipSourcesEqual(a: ?PromotionLeadershipSource, b: ?PromotionLeadershipSource) bool {
        if (a == null or b == null) return a == null and b == null;
        return a.?.ptr == b.?.ptr and a.?.vtable == b.?.vtable;
    }

    fn haWriteGatesEqual(a: ?db_mod.HAWriteGate, b: ?db_mod.HAWriteGate) bool {
        if (a == null or b == null) return a == null and b == null;
        return switch (a.?) {
            .primary => |left| switch (b.?) {
                .primary => |right| left == right,
                .fenced_primary => false,
                .standby => false,
                .shared => false,
            },
            .fenced_primary => |left| switch (b.?) {
                .primary => false,
                .fenced_primary => |right| left.primary == right.primary and
                    left.fence_store == right.fence_store and
                    std.mem.eql(u8, left.node_id, right.node_id),
                .standby => false,
                .shared => false,
            },
            .standby => |left| switch (b.?) {
                .primary => false,
                .fenced_primary => false,
                .standby => |right| left == right,
                .shared => false,
            },
            .shared => |left| switch (b.?) {
                .primary, .fenced_primary, .standby => false,
                .shared => |right| left.state == right.state and left.generation == right.generation,
            },
        };
    }

    fn haWriteGateCurrentGeneration(gate: ?db_mod.HAWriteGate) ?u64 {
        const configured = gate orelse return null;
        return switch (configured) {
            .shared => |shared| shared.state.currentGeneration(),
            .primary, .fenced_primary, .standby => null,
        };
    }

    fn syncPoliciesEqual(a: ha_primary_mod.SyncPolicy, b: ha_primary_mod.SyncPolicy) bool {
        if (a.mode != b.mode or
            a.selection != b.selection or
            a.required != b.required or
            a.failure_policy != b.failure_policy or
            a.standby_names.len != b.standby_names.len)
        {
            return false;
        }
        for (a.standby_names, b.standby_names) |left, right| {
            if (!std.mem.eql(u8, left, right)) return false;
        }
        return true;
    }

    fn haAsyncMirrorsEqual(a: ?db_mod.HAAsyncEffectMirror, b: ?db_mod.HAAsyncEffectMirror) bool {
        if (a == null or b == null) return a == null and b == null;
        const left = a.?;
        const right = b.?;
        return left.primary == right.primary and
            left.last_lsn == right.last_lsn and
            left.failure_count == right.failure_count and
            syncPoliciesEqual(left.sync_policy, right.sync_policy) and
            left.sync_wait_ctx == right.sync_wait_ctx and
            left.sync_wait_fn == right.sync_wait_fn and
            left.last_gate_lsn == right.last_gate_lsn and
            left.last_gate_action == right.last_gate_action and
            left.sync_reject_count == right.sync_reject_count and
            left.sync_wait_count == right.sync_wait_count and
            left.sync_degraded_count == right.sync_degraded_count;
    }

    fn runtimeHooksEqual(
        self: *const ProvisionedTableWriteCache,
        candidate_source: ?db_mod.CandidateSource,
        entity_sink_value: ?db_mod.EntitySink,
        leadership_source: ?PromotionLeadershipSource,
    ) bool {
        return candidateSourcesEqual(self.resolution_candidate_source, candidate_source) and
            entitySinksEqual(self.entity_sink, entity_sink_value) and
            promotionLeadershipSourcesEqual(self.promotion_leadership_source, leadership_source);
    }

    fn setRuntimeHooksLocked(
        self: *ProvisionedTableWriteCache,
        candidate_source: ?db_mod.CandidateSource,
        entity_sink_value: ?db_mod.EntitySink,
        leadership_source: ?PromotionLeadershipSource,
    ) void {
        if (self.runtimeHooksEqual(candidate_source, entity_sink_value, leadership_source)) return;
        self.resolution_candidate_source = candidate_source;
        self.entity_sink = entity_sink_value;
        self.promotion_leadership_source = leadership_source;
        self.refreshRuntimeHooksLocked();
    }

    pub fn setResolutionCandidateSource(self: *ProvisionedTableWriteCache, source: ?db_mod.CandidateSource) void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        if (candidateSourcesEqual(self.resolution_candidate_source, source)) return;
        self.resolution_candidate_source = source;
        self.refreshRuntimeHooksLocked();
    }

    pub fn setEntitySink(self: *ProvisionedTableWriteCache, sink: ?db_mod.EntitySink) void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        if (entitySinksEqual(self.entity_sink, sink)) return;
        self.entity_sink = sink;
        self.refreshRuntimeHooksLocked();
    }

    pub fn setPromotionLeadershipSource(self: *ProvisionedTableWriteCache, source: ?PromotionLeadershipSource) void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        if (promotionLeadershipSourcesEqual(self.promotion_leadership_source, source)) return;
        self.promotion_leadership_source = source;
        self.refreshRuntimeHooksLocked();
    }

    fn setHAWriteGate(self: *ProvisionedTableWriteCache, gate: ?db_mod.HAWriteGate) !void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        if (haWriteGatesEqual(self.ha_write_gate, gate)) return;
        lockAtomic(&self.entry_lifecycle_mutex);
        self.reserveClearCapacityAssumeLifecycleLocked() catch |err| {
            self.entry_lifecycle_mutex.unlock();
            return err;
        };
        self.ha_write_gate = gate;
        self.clearAssumeLifecycleLocked();
        self.entry_lifecycle_mutex.unlock();
        self.drainPendingClosesAssumeOpenMutexHeld();
    }

    fn setHAMirror(self: *ProvisionedTableWriteCache, mirror: ?db_mod.HAAsyncEffectMirror) !void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        if (haAsyncMirrorsEqual(self.ha_async_mirror, mirror)) return;
        lockAtomic(&self.entry_lifecycle_mutex);
        self.reserveClearCapacityAssumeLifecycleLocked() catch |err| {
            self.entry_lifecycle_mutex.unlock();
            return err;
        };
        self.ha_async_mirror = mirror;
        self.clearAssumeLifecycleLocked();
        self.entry_lifecycle_mutex.unlock();
        self.drainPendingClosesAssumeOpenMutexHeld();
    }

    const ActiveBulkIngestSession = struct {
        table_name: []u8,
        depth: usize = 1,

        fn deinit(self: *ActiveBulkIngestSession, alloc: std.mem.Allocator) void {
            alloc.free(self.table_name);
            self.* = undefined;
        }
    };

    const TableMetadata = struct {
        table_name: []u8,
        indexes_json: ?[]u8,
        schema_json: ?[]u8,

        fn deinit(self: *TableMetadata, alloc: std.mem.Allocator) void {
            alloc.free(self.table_name);
            if (self.indexes_json) |value| alloc.free(value);
            if (self.schema_json) |value| alloc.free(value);
            self.* = undefined;
        }
    };

    fn cloneTableMetadataAlloc(
        self: *ProvisionedTableWriteCache,
        table_name: []const u8,
        indexes_json: ?[]const u8,
        schema_json: ?[]const u8,
    ) !TableMetadata {
        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer self.alloc.free(owned_table_name);
        const owned_indexes_json = if (indexes_json) |value| try self.alloc.dupe(u8, value) else null;
        errdefer if (owned_indexes_json) |value| self.alloc.free(value);
        const owned_schema_json = if (schema_json) |value| try self.alloc.dupe(u8, value) else null;
        errdefer if (owned_schema_json) |value| self.alloc.free(value);
        return .{
            .table_name = owned_table_name,
            .indexes_json = owned_indexes_json,
            .schema_json = owned_schema_json,
        };
    }

    pub fn init(alloc: std.mem.Allocator) ProvisionedTableWriteCache {
        return .{ .alloc = alloc };
    }

    pub fn deinit(self: *ProvisionedTableWriteCache) void {
        for (self.entries.items) |entry| {
            entry.deinit(self.alloc);
            self.alloc.destroy(entry);
        }
        self.entries.deinit(self.alloc);
        for (self.retired_entries.items) |entry| {
            entry.deinit(self.alloc);
            self.alloc.destroy(entry);
        }
        self.retired_entries.deinit(self.alloc);
        for (self.closing_entries.items) |entry| {
            entry.deinit(self.alloc);
            self.alloc.destroy(entry);
        }
        self.closing_entries.deinit(self.alloc);
        for (self.table_metadata.items) |*metadata| metadata.deinit(self.alloc);
        self.table_metadata.deinit(self.alloc);
        for (self.active_bulk_ingest_sessions.items) |*session| session.deinit(self.alloc);
        self.active_bulk_ingest_sessions.deinit(self.alloc);
        self.* = undefined;
    }

    fn reserveClearCapacityAssumeLifecycleLocked(self: *ProvisionedTableWriteCache) !void {
        try self.retired_entries.ensureUnusedCapacity(self.alloc, self.entries.items.len);
        try self.closing_entries.ensureUnusedCapacity(self.alloc, self.entries.items.len);
    }

    fn clearAssumeLifecycleLocked(self: *ProvisionedTableWriteCache) void {
        for (self.entries.items) |entry| self.retireEntryAssumeLifecycleLocked(entry);
        self.entries.clearRetainingCapacity();
        for (self.table_metadata.items) |*metadata| metadata.deinit(self.alloc);
        self.table_metadata.clearRetainingCapacity();
        for (self.active_bulk_ingest_sessions.items) |*session| session.deinit(self.alloc);
        self.active_bulk_ingest_sessions.clearRetainingCapacity();
    }

    pub fn cacheStats(self: *const ProvisionedTableWriteCache) CacheStats {
        return .{
            .hit_count = self.hit_count.load(.monotonic),
            .miss_count = self.miss_count.load(.monotonic),
        };
    }

    pub fn autoBulkIngestStatsLocked(self: *const ProvisionedTableWriteCache, now_ns: u64) AutoBulkIngestStats {
        var stats = AutoBulkIngestStats{
            .cached_entries = @intCast(self.entries.items.len),
            .active_bulk_sessions = @intCast(self.active_bulk_ingest_sessions.items.len),
        };
        for (self.entries.items) |entry| {
            stats.active_leases += self.entryActiveLeasesLocked(entry);
            if (!entry.auto_bulk_ingest_session_open) continue;
            stats.open_entries += 1;
            stats.total_ops += entry.auto_bulk_ingest_ops;
            if (entry.auto_bulk_ingest_finish_requested) stats.finish_requested_entries += 1;
            if (entry.auto_bulk_ingest_last_ns > 0) {
                const idle_ns = now_ns -| entry.auto_bulk_ingest_last_ns;
                stats.oldest_idle_ns = @max(stats.oldest_idle_ns, idle_ns);
                if (idle_ns >= auto_bulk_ingest_max_idle_ns) stats.idle_expired_entries += 1;
            }
        }
        return stats;
    }

    pub fn diagnosticsLocked(self: *const ProvisionedTableWriteCache) Diagnostics {
        var stats = Diagnostics{
            .cached_entries = @intCast(self.entries.items.len),
            .table_metadata_entries = @intCast(self.table_metadata.items.len),
            .active_bulk_sessions = @intCast(self.active_bulk_ingest_sessions.items.len),
        };
        for (self.entries.items) |entry| {
            stats.active_leases += self.entryActiveLeasesLocked(entry);
            if (entry.bulk_ingest_session_open) stats.bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_session_open) stats.auto_bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_finish_requested) stats.auto_bulk_ingest_finish_requested_entries += 1;
            accumulateDiagnosticsLsmStats(&stats, entry.db.trySnapshotLsmMaintenanceStats());
        }
        lockAtomic(@constCast(&self.entry_lifecycle_mutex));
        defer @constCast(&self.entry_lifecycle_mutex).unlock();
        stats.retired_entries = @intCast(self.retired_entries.items.len + self.closing_entries.items.len);
        for (self.retired_entries.items) |entry| {
            stats.retired_active_leases += entry.active_leases;
            if (entry.bulk_ingest_session_open) stats.bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_session_open) stats.auto_bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_finish_requested) stats.auto_bulk_ingest_finish_requested_entries += 1;
            accumulateDiagnosticsLsmStats(&stats, entry.db.trySnapshotLsmMaintenanceStats());
        }
        for (self.closing_entries.items) |entry| {
            if (entry.bulk_ingest_session_open) stats.bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_session_open) stats.auto_bulk_ingest_open_entries += 1;
            if (entry.auto_bulk_ingest_finish_requested) stats.auto_bulk_ingest_finish_requested_entries += 1;
            accumulateDiagnosticsLsmStats(&stats, entry.db.trySnapshotLsmMaintenanceStats());
        }
        return stats;
    }

    fn accumulateDiagnosticsLsmStats(stats: *Diagnostics, maintenance: ?lsm_backend.Backend.MaintenanceStats) void {
        const value = maintenance orelse return;
        stats.lsm_mutable_bytes +|= value.mutable_bytes;
        stats.lsm_immutable_bytes +|= value.immutable_bytes;
        stats.lsm_total_run_bytes +|= value.total_run_bytes;
        stats.lsm_wal_retained_bytes +|= value.wal_retained_bytes;
        stats.lsm_wal_retained_segments +|= value.wal_retained_segments;
        stats.lsm_active_readers +|= value.active_readers;
        stats.lsm_obsolete_paths +|= value.obsolete_paths;
        stats.lsm_bulk_ingest_current_scan_clone_active_bytes +|= value.bulk_ingest_current_scan_clone_active_bytes;
    }

    pub fn autoBulkIngestMaxIdleNs() u64 {
        return auto_bulk_ingest_max_idle_ns;
    }

    pub fn getOrOpenLocked(
        self: *ProvisionedTableWriteCache,
        path: []const u8,
        catalog: table_catalog.CatalogSource,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) !CachedDb {
        return try self.getOrOpenLockedMode(path, catalog, group_id, lsm_root_generation, table_name, .default);
    }

    fn getOrOpenLockedMode(
        self: *ProvisionedTableWriteCache,
        path: []const u8,
        catalog: table_catalog.CatalogSource,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
    ) !CachedDb {
        const OpenedDb = struct {
            db: db_mod.DB,
            start_bulk_session: bool,
        };

        const openDbForMode = struct {
            fn run(
                allocator: std.mem.Allocator,
                db_path: []const u8,
                indexes_json: ?[]const u8,
                cache: ?*lsm_backend.Cache,
                vector_cache: ?*hbc_mod.Cache,
                root_generation: u64,
                manager: ?*resource_manager_mod.ResourceManager,
                open_mode: ManagedDbOpenMode,
                runtime: ?*db_mod.background_runtime.BackendRuntime,
                antfly_provider: ?managed_embedder.AntflyProvider,
                secret_store: ?*common_secrets.FileStore,
                identity_namespace: ?doc_identity.Namespace,
                ha_write_gate: ?db_mod.HAWriteGate,
                ha_async_mirror: ?db_mod.HAAsyncEffectMirror,
                inference_api_url: ?[]const u8,
            ) !OpenedDb {
                const effective_ha_mirror = haMirrorForManagedDbOpenMode(open_mode, ha_async_mirror);
                var db = if (indexes_json) |managed_indexes_json|
                    try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                        allocator,
                        db_path,
                        managed_indexes_json,
                        cache,
                        vector_cache,
                        root_generation,
                        manager,
                        open_mode,
                        runtime,
                        antfly_provider,
                        secret_store,
                        null,
                        identity_namespace,
                        .{
                            .drain_resolver_backfill = false,
                            .inference_api_url = inference_api_url,
                            .ha_write_gate = ha_write_gate,
                            .ha_async_effect_mirror = effective_ha_mirror,
                            .ha_async_batch_mirror = effective_ha_mirror,
                            .ha_async_metadata_mirror = effective_ha_mirror,
                        },
                    )
                else
                    try db_mod.DB.open(allocator, db_path, .{
                        .lsm_cache = cache,
                        .hbc_cache = vector_cache,
                        .lsm_root_generation = root_generation,
                        .resource_manager = manager,
                        .backend_runtime = runtime,
                        .identity_namespace = identity_namespace,
                        .prefer_existing_identity_namespace = identity_namespace != null,
                        .ha_write_gate = ha_write_gate,
                        .ha_async_effect_mirror = effective_ha_mirror,
                        .ha_async_batch_mirror = effective_ha_mirror,
                        .ha_async_metadata_mirror = effective_ha_mirror,
                        .open_mode = switch (open_mode) {
                            .default => .writer,
                            .default_async, .writer_no_replay => .writer_no_replay,
                            .startup_catch_up, .restore_repair => .writer_no_replay,
                            .query_readonly => .query_readonly,
                            .status_only => .status_only,
                        },
                        .start_index_workers = if (open_mode == .startup_catch_up or open_mode == .restore_repair or open_mode == .query_readonly) false else true,
                        .start_optional_runtimes = open_mode != .startup_catch_up and open_mode != .restore_repair and open_mode != .query_readonly,
                        .index_open_parallelism = if (open_mode == .default_async or open_mode == .writer_no_replay) 1 else null,
                    });
                errdefer db.close();
                try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
                return .{
                    .db = db,
                    .start_bulk_session = switch (open_mode) {
                        .default, .default_async, .writer_no_replay => true,
                        .startup_catch_up, .restore_repair, .query_readonly, .status_only => false,
                    },
                };
            }
        }.run;

        const metadata = try self.getOrLoadMetadataLocked(catalog, table_name);
        const identity_namespace = try loadTableIdentityNamespaceForGroup(self.alloc, catalog, table_name, group_id);
        try self.pruneStaleEntriesForGroupTableLocked(group_id, lsm_root_generation, table_name);
        if (self.hasPendingCloseForGroupTableLocked(group_id, table_name)) {
            return error.LsmRootWriterAlreadyOpen;
        }
        if (mode != .status_only and mode != .query_readonly and self.hasRetiredActiveLeaseForGroupTableLocked(group_id, table_name)) {
            return error.LsmRootWriterAlreadyOpen;
        }
        if (mode == .status_only) {
            const opened = try openDbForMode(
                self.alloc,
                path,
                metadata.indexes_json,
                self.lsm_cache,
                self.hbc_cache,
                lsm_root_generation,
                self.resource_manager,
                mode,
                self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                identity_namespace,
                self.ha_write_gate,
                self.ha_async_mirror,
                self.inference_api_url,
            );
            const owned_db = try self.alloc.create(db_mod.DB);
            errdefer self.alloc.destroy(owned_db);
            owned_db.* = opened.db;
            return .{
                .cache = self,
                .db = owned_db,
                .schema_json = metadata.schema_json,
                .owned_db = owned_db,
            };
        }
        for (self.entries.items) |entry| {
            if (entry.group_id == group_id and entry.lsm_root_generation == lsm_root_generation and std.mem.eql(u8, entry.table_name, table_name)) {
                if (!self.entryHAWriteGateCurrent(entry)) continue;
                _ = self.hit_count.fetchAdd(1, .monotonic);
                lockAtomic(&self.entry_lifecycle_mutex);
                defer self.entry_lifecycle_mutex.unlock();
                entry.active_leases += 1;
                return .{
                    .cache = self,
                    .entry = entry,
                    .db = &entry.db,
                    .schema_json = entry.schema_json,
                };
            }
        }
        if (mode != .status_only and mode != .query_readonly) {
            for (self.entries.items) |entry| {
                if (entry.group_id != group_id) continue;
                if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
                return error.LsmRootWriterAlreadyOpen;
            }
        }

        _ = self.miss_count.fetchAdd(1, .monotonic);
        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer self.alloc.free(owned_table_name);
        var opened = try openDbForMode(
            self.alloc,
            path,
            metadata.indexes_json,
            self.lsm_cache,
            self.hbc_cache,
            lsm_root_generation,
            self.resource_manager,
            mode,
            self.backend_runtime,
            self.antfly_provider,
            self.secret_store,
            identity_namespace,
            self.ha_write_gate,
            self.ha_async_mirror,
            self.inference_api_url,
        );
        errdefer opened.db.close();
        const start_bulk_session = opened.start_bulk_session and self.bulkIngestSessionActiveForTable(table_name);
        if (start_bulk_session) {
            try opened.db.beginBulkIngestSession();
            errdefer opened.db.abortBulkIngestSession();
        }
        try self.reserveInstalledEntryLifecycleCapacityLocked(1);
        const owned_entry = try self.alloc.create(Entry);
        errdefer self.alloc.destroy(owned_entry);
        owned_entry.* = .{
            .group_id = group_id,
            .lsm_root_generation = lsm_root_generation,
            .ha_write_gate_generation = haWriteGateCurrentGeneration(self.ha_write_gate),
            .table_name = owned_table_name,
            .db = opened.db,
            .schema_json = if (metadata.schema_json) |value| try self.alloc.dupe(u8, value) else null,
            .active_leases = 1,
            .bulk_ingest_session_open = start_bulk_session,
        };
        self.applyRuntimeHooksToDb(&owned_entry.db, group_id, &owned_entry.promotion_owner_state);
        try self.entries.append(self.alloc, owned_entry);
        var cached = CachedDb{
            .cache = self,
            .entry = owned_entry,
            .db = &owned_entry.db,
            .schema_json = owned_entry.schema_json,
        };
        errdefer self.retireFailedOpenLocked(&cached);
        try owned_entry.db.drainResolverBackfill();
        return cached;
    }

    fn adoptSeededEntryGenerationLocked(self: *ProvisionedTableWriteCache, entry: *Entry, lsm_root_generation: u64) bool {
        if (!entry.allow_generation_adoption) return false;
        if (self.entryActiveLeasesLocked(entry) != 0 and !entry.allow_active_generation_adoption) return false;
        if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) return false;
        // The seeded entry already owns the only writable backend for this root.
        // Updating its visible generation in place keeps concurrent leases on the
        // same writer instead of forcing a second physical open.
        entry.lsm_root_generation = lsm_root_generation;
        return true;
    }

    fn getOrPrepareOpenLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        expected_identity_namespace: ?doc_identity.Namespace,
    ) !GetOrPrepareOpen {
        try self.pruneStaleEntriesForGroupTableLocked(group_id, lsm_root_generation, table_name);
        try self.pruneIdentityMismatchedEntriesForGroupTableLocked(group_id, table_name, expected_identity_namespace);
        if (self.hasRetiredActiveLeaseForGroupTableLocked(group_id, table_name)) {
            return error.LsmRootWriterAlreadyOpen;
        }
        if (self.hasPendingCloseForGroupTableLocked(group_id, table_name)) {
            return .pending_close;
        }
        for (self.entries.items) |entry| {
            if (entry.group_id == group_id and entry.lsm_root_generation == lsm_root_generation and std.mem.eql(u8, entry.table_name, table_name)) {
                if (!self.entryHAWriteGateCurrent(entry)) continue;
                if (!entryMatchesExpectedIdentityNamespace(entry, expected_identity_namespace)) continue;
                _ = self.hit_count.fetchAdd(1, .monotonic);
                lockAtomic(&self.entry_lifecycle_mutex);
                defer self.entry_lifecycle_mutex.unlock();
                entry.active_leases += 1;
                return .{
                    .cached = .{
                        .cache = self,
                        .entry = entry,
                        .db = &entry.db,
                        .schema_json = entry.schema_json,
                    },
                };
            }
        }
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            if (!entryMatchesExpectedIdentityNamespace(entry, expected_identity_namespace)) continue;
            if (!self.adoptSeededEntryGenerationLocked(entry, lsm_root_generation)) continue;
            _ = self.hit_count.fetchAdd(1, .monotonic);
            lockAtomic(&self.entry_lifecycle_mutex);
            defer self.entry_lifecycle_mutex.unlock();
            entry.active_leases += 1;
            return .{
                .cached = .{
                    .cache = self,
                    .entry = entry,
                    .db = &entry.db,
                    .schema_json = entry.schema_json,
                },
            };
        }
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return error.LsmRootWriterAlreadyOpen;
        }

        _ = self.miss_count.fetchAdd(1, .monotonic);
        return .{ .prepared = .{} };
    }

    fn pruneIdentityMismatchedEntriesForGroupTableLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
        expected: ?doc_identity.Namespace,
    ) !void {
        const namespace = expected orelse return;
        var mismatch_count: usize = 0;
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!entry.db.core.identity_namespace.eql(namespace)) mismatch_count += 1;
        }
        try self.reserveLifecycleRetireCapacityLocked(mismatch_count);

        var i: usize = 0;
        while (i < self.entries.items.len) {
            const entry = self.entries.items[i];
            if (entry.group_id != group_id or
                !std.mem.eql(u8, entry.table_name, table_name) or
                entry.db.core.identity_namespace.eql(namespace))
            {
                i += 1;
                continue;
            }
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                i += 1;
                continue;
            }
            if (try self.retireInactiveEntryAtIndexForCloseLocked(i)) continue;
            i += 1;
        }
    }

    fn entryMatchesExpectedIdentityNamespace(entry: *const Entry, expected: ?doc_identity.Namespace) bool {
        const namespace = expected orelse return true;
        return entry.db.core.identity_namespace.eql(namespace);
    }

    fn snapshotLeaseLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) ?CachedDb {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (entry.lsm_root_generation != lsm_root_generation) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            return self.leaseEntryLocked(entry);
        }
        return null;
    }

    fn snapshotLeaseOrAdoptSeededLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) ?CachedDb {
        if (self.snapshotLeaseLocked(group_id, lsm_root_generation, table_name)) |cached| return cached;
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            if (!self.adoptSeededEntryGenerationLocked(entry, lsm_root_generation)) continue;
            return self.leaseEntryLocked(entry);
        }
        return null;
    }

    fn snapshotGroupLeaseOrAdoptSeededLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
    ) ?CachedDb {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            if (entry.lsm_root_generation != lsm_root_generation and
                !self.adoptSeededEntryGenerationLocked(entry, lsm_root_generation)) continue;
            return self.leaseEntryLocked(entry);
        }
        return null;
    }

    fn leaseEntryLocked(self: *ProvisionedTableWriteCache, entry: *Entry) CachedDb {
        lockAtomic(@constCast(&self.entry_lifecycle_mutex));
        defer @constCast(&self.entry_lifecycle_mutex).unlock();
        entry.active_leases += 1;
        return .{
            .cache = self,
            .entry = entry,
            .db = &entry.db,
            .schema_json = entry.schema_json,
        };
    }

    fn leaseLiveEntryForLocalMutationLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
        allow_bulk_session: bool,
    ) ?CachedDb {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!allow_bulk_session and (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open)) return null;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            return self.leaseEntryLocked(entry);
        }
        return null;
    }

    fn publishCachedLeaseGeneration(
        self: *ProvisionedTableWriteCache,
        cached: *const CachedDb,
        lsm_root_generation: u64,
    ) void {
        _ = self;
        const entry = cached.entry orelse return;
        entry.lsm_root_generation = lsm_root_generation;
        entry.allow_generation_adoption = false;
        entry.allow_active_generation_adoption = false;
    }

    fn adoptPreparedOpenLocked(
        self: *ProvisionedTableWriteCache,
        opened: *?db_mod.DB,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        mode: ManagedDbOpenMode,
        prepared: *PreparedOpen,
    ) !CachedDb {
        try self.pruneStaleEntriesForGroupTableLocked(group_id, lsm_root_generation, table_name);
        if (self.hasPendingCloseForGroupTableLocked(group_id, table_name)) {
            return error.LsmRootWriterAlreadyOpen;
        }
        for (self.entries.items) |entry| {
            if (entry.group_id == group_id and entry.lsm_root_generation == lsm_root_generation and std.mem.eql(u8, entry.table_name, table_name)) {
                if (!self.entryHAWriteGateCurrent(entry)) continue;
                if (opened.*) |*db| db.close();
                opened.* = null;
                _ = self.hit_count.fetchAdd(1, .monotonic);
                lockAtomic(&self.entry_lifecycle_mutex);
                defer self.entry_lifecycle_mutex.unlock();
                entry.active_leases += 1;
                return .{
                    .cache = self,
                    .entry = entry,
                    .db = &entry.db,
                    .schema_json = entry.schema_json,
                };
            }
        }

        var db = opened.* orelse unreachable;
        opened.* = null;
        errdefer db.close();

        const start_bulk_session = switch (mode) {
            .default, .default_async, .writer_no_replay => self.bulkIngestSessionActiveForTable(table_name),
            .startup_catch_up, .restore_repair, .query_readonly, .status_only => false,
        };
        if (start_bulk_session) {
            try db.beginBulkIngestSession();
            errdefer db.abortBulkIngestSession();
        }

        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer self.alloc.free(owned_table_name);
        try self.reserveInstalledEntryLifecycleCapacityLocked(1);
        const owned_entry = try self.alloc.create(Entry);
        errdefer self.alloc.destroy(owned_entry);
        owned_entry.* = .{
            .group_id = group_id,
            .lsm_root_generation = lsm_root_generation,
            .ha_write_gate_generation = haWriteGateCurrentGeneration(self.ha_write_gate),
            .table_name = owned_table_name,
            .db = db,
            .schema_json = prepared.schema_json,
            .active_leases = 1,
            .bulk_ingest_session_open = start_bulk_session,
        };
        self.applyRuntimeHooksToDb(&owned_entry.db, group_id, &owned_entry.promotion_owner_state);
        prepared.schema_json = null;
        errdefer owned_entry.deinit(self.alloc);
        try self.entries.append(self.alloc, owned_entry);
        opened.* = null;
        return .{
            .cache = self,
            .entry = owned_entry,
            .db = &owned_entry.db,
            .schema_json = owned_entry.schema_json,
        };
    }

    fn seedCreatedDbLocked(
        self: *ProvisionedTableWriteCache,
        opened: *?db_mod.DB,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
        indexes_json: []const u8,
        schema_json: []const u8,
    ) !void {
        try self.pruneStaleEntriesForGroupTableLocked(group_id, lsm_root_generation, table_name);
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (entry.lsm_root_generation != lsm_root_generation) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!self.entryHAWriteGateCurrent(entry)) continue;
            if (opened.*) |*db| db.close();
            opened.* = null;
            try self.replaceTableMetadataLocked(table_name, indexes_json, schema_json);
            return;
        }

        var db = opened.* orelse unreachable;
        opened.* = null;
        errdefer db.close();

        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer self.alloc.free(owned_table_name);
        const owned_schema_json = try self.alloc.dupe(u8, schema_json);
        errdefer self.alloc.free(owned_schema_json);
        try self.reserveInstalledEntryLifecycleCapacityLocked(1);
        const owned_entry = try self.alloc.create(Entry);
        errdefer self.alloc.destroy(owned_entry);
        owned_entry.* = .{
            .group_id = group_id,
            .lsm_root_generation = lsm_root_generation,
            .ha_write_gate_generation = haWriteGateCurrentGeneration(self.ha_write_gate),
            .table_name = owned_table_name,
            .db = db,
            .schema_json = owned_schema_json,
            .active_leases = 0,
            .allow_generation_adoption = true,
            .allow_active_generation_adoption = true,
        };
        self.applyRuntimeHooksToDb(&owned_entry.db, group_id, &owned_entry.promotion_owner_state);
        errdefer owned_entry.deinit(self.alloc);

        try self.replaceTableMetadataLocked(table_name, indexes_json, schema_json);
        try self.entries.append(self.alloc, owned_entry);
    }

    pub fn getLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) ?*db_mod.DB {
        for (self.entries.items) |entry| {
            if (entry.group_id == group_id and entry.lsm_root_generation == lsm_root_generation and std.mem.eql(u8, entry.table_name, table_name)) return &entry.db;
        }
        return null;
    }

    pub fn snapshotRuntimeStatusesLocked(
        self: *ProvisionedTableWriteCache,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        var count: usize = 0;
        for (self.entries.items) |entry| {
            if (std.mem.eql(u8, entry.table_name, table_name)) count += 1;
        }
        if (count == 0) return null;

        const items = try alloc.alloc(runtime_status.LocalTableRuntimeStatus, count);
        var initialized: usize = 0;
        errdefer {
            for (items[0..initialized]) |*item| item.deinit(alloc);
            alloc.free(items);
        }

        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            items[initialized] = .{
                .group_id = entry.group_id,
                .stats = try entry.db.runtimeStatusStatsConsistent(alloc),
            };
            markRuntimeStatusFromDb(&items[initialized], .idle);
            initialized += 1;
        }
        return .{ .items = items };
    }

    fn pruneStaleEntriesForGroupTableLocked(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        lsm_root_generation: u64,
        table_name: []const u8,
    ) !void {
        var i: usize = 0;
        while (i < self.entries.items.len) {
            const entry = self.entries.items[i];
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name)) {
                i += 1;
                continue;
            }
            const stale_ha_write_gate = !self.entryHAWriteGateCurrent(entry);
            if (entry.lsm_root_generation == lsm_root_generation and !stale_ha_write_gate) {
                i += 1;
                continue;
            }
            if (!stale_ha_write_gate and self.adoptSeededEntryGenerationLocked(entry, lsm_root_generation)) {
                i += 1;
                continue;
            }
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                i += 1;
                continue;
            }
            if (try self.retireInactiveEntryAtIndexForCloseLocked(i)) continue;
            i += 1;
        }
    }

    fn invalidateTable(self: *ProvisionedTableWriteCache, table_name: []const u8) void {
        self.removeDbEntriesForTable(table_name);

        var i: usize = 0;
        while (i < self.table_metadata.items.len) {
            if (!std.mem.eql(u8, self.table_metadata.items[i].table_name, table_name)) {
                i += 1;
                continue;
            }
            var removed = self.table_metadata.orderedRemove(i);
            removed.deinit(self.alloc);
        }
    }

    fn retireDbEntriesForTableLocked(self: *ProvisionedTableWriteCache, table_name: []const u8) !void {
        var matching_entries: usize = 0;
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            matching_entries += 1;
        }
        try self.reserveLifecycleRetireCapacityLocked(matching_entries);

        var i: usize = 0;
        while (i < self.entries.items.len) {
            if (!std.mem.eql(u8, self.entries.items[i].table_name, table_name)) {
                i += 1;
                continue;
            }
            const removed = self.entries.orderedRemove(i);
            self.retireEntryLocked(removed);
        }
    }

    fn removeDbEntriesForTable(self: *ProvisionedTableWriteCache, table_name: []const u8) void {
        self.retireDbEntriesForTableLocked(table_name) catch return;
    }

    fn hasLiveEntryForGroupTableLocked(
        self: *const ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) bool {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return true;
        }
        return false;
    }

    fn hasLiveEntryForTableLocked(
        self: *const ProvisionedTableWriteCache,
        table_name: []const u8,
    ) bool {
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return true;
        }
        return false;
    }

    fn hasRetiredActiveLeaseForGroupTableLocked(
        self: *const ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) bool {
        lockAtomic(@constCast(&self.entry_lifecycle_mutex));
        defer @constCast(&self.entry_lifecycle_mutex).unlock();
        for (self.retired_entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (entry.active_leases == 0) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return true;
        }
        return false;
    }

    fn hasPendingCloseForGroupTableLocked(
        self: *const ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) bool {
        lockAtomic(@constCast(&self.entry_lifecycle_mutex));
        defer @constCast(&self.entry_lifecycle_mutex).unlock();
        for (self.closing_entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return true;
        }
        for (self.retired_entries.items) |entry| {
            if (entry.group_id != group_id) continue;
            if (entry.active_leases != 0) continue;
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            return true;
        }
        return false;
    }

    fn hasForegroundStateForGroupTableLocked(
        self: *const ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) bool {
        if (self.bulkIngestSessionActiveForTable(table_name)) return true;
        if (self.hasLiveEntryForGroupTableLocked(group_id, table_name)) return true;
        return self.hasRetiredActiveLeaseForGroupTableLocked(group_id, table_name);
    }

    pub fn beginBulkIngestLocked(self: *ProvisionedTableWriteCache, table_name: []const u8) !void {
        for (self.active_bulk_ingest_sessions.items) |*session| {
            if (!std.mem.eql(u8, session.table_name, table_name)) continue;
            session.depth += 1;
            return;
        }

        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer self.alloc.free(owned_table_name);
        try self.active_bulk_ingest_sessions.ensureUnusedCapacity(self.alloc, 1);
        var started_any = false;
        errdefer if (started_any) {
            for (self.entries.items) |entry| {
                if (!std.mem.eql(u8, entry.table_name, table_name) or !entry.bulk_ingest_session_open) continue;
                entry.db.abortBulkIngestSession();
                entry.bulk_ingest_session_open = false;
            }
        };
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name) or entry.bulk_ingest_session_open) continue;
            try entry.db.beginBulkIngestSession();
            entry.bulk_ingest_session_open = true;
            entry.auto_bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_ops = 0;
            entry.auto_bulk_ingest_started_ns = 0;
            entry.auto_bulk_ingest_last_ns = 0;
            entry.auto_bulk_ingest_finish_requested = false;
            started_any = true;
        }
        self.active_bulk_ingest_sessions.appendAssumeCapacity(.{ .table_name = owned_table_name });
    }

    pub fn finishBulkIngestLocked(
        self: *ProvisionedTableWriteCache,
        table_name: []const u8,
        options: backend_types.BulkIngestFinishOptions,
    ) !void {
        const idx = self.findActiveBulkIngestSession(table_name) orelse return;
        if (self.active_bulk_ingest_sessions.items[idx].depth > 1) {
            self.active_bulk_ingest_sessions.items[idx].depth -= 1;
            return;
        }

        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name) or !entry.bulk_ingest_session_open) continue;
            if (entry.auto_bulk_ingest_session_open) {
                try entry.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(options);
            } else {
                try entry.db.finishBulkIngestSessionWithOptions(options);
            }
            entry.bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_ops = 0;
            entry.auto_bulk_ingest_started_ns = 0;
            entry.auto_bulk_ingest_last_ns = 0;
            entry.auto_bulk_ingest_finish_requested = false;
        }
        var removed = self.active_bulk_ingest_sessions.orderedRemove(idx);
        removed.deinit(self.alloc);
    }

    pub fn abortBulkIngestLocked(self: *ProvisionedTableWriteCache, table_name: []const u8) void {
        const idx = self.findActiveBulkIngestSession(table_name) orelse return;
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name) or !entry.bulk_ingest_session_open) continue;
            if (entry.auto_bulk_ingest_session_open) {
                entry.db.abortPrimaryStoreAutoBulkIngestSession();
            } else {
                entry.db.abortBulkIngestSession();
            }
            entry.bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_ops = 0;
            entry.auto_bulk_ingest_started_ns = 0;
            entry.auto_bulk_ingest_last_ns = 0;
            entry.auto_bulk_ingest_finish_requested = false;
        }
        var removed = self.active_bulk_ingest_sessions.orderedRemove(idx);
        removed.deinit(self.alloc);
    }

    pub fn ensureAutoBulkIngestLocked(self: *ProvisionedTableWriteCache, group_id: u64, table_name: []const u8, now_ns: u64) !void {
        if (self.bulkIngestSessionActiveForTable(table_name)) return;
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!entry.bulk_ingest_session_open) {
                try entry.db.beginPrimaryStoreAutoBulkIngestSession();
                entry.bulk_ingest_session_open = true;
            }
            entry.auto_bulk_ingest_session_open = true;
            if (entry.auto_bulk_ingest_started_ns == 0) entry.auto_bulk_ingest_started_ns = now_ns;
            entry.auto_bulk_ingest_last_ns = now_ns;
            return;
        }
    }

    pub fn recordAutoBulkIngestOpsLocked(self: *ProvisionedTableWriteCache, group_id: u64, table_name: []const u8, ops: usize, now_ns: u64) !void {
        if (ops == 0) return;
        var should_finish = false;
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name) or !entry.auto_bulk_ingest_session_open) continue;
            entry.auto_bulk_ingest_ops +|= ops;
            entry.auto_bulk_ingest_last_ns = now_ns;
            should_finish = should_finish or entry.auto_bulk_ingest_ops >= auto_bulk_ingest_max_window_ops;
            if (should_finish) entry.auto_bulk_ingest_finish_requested = true;
        }
    }

    pub fn rollRequestedAutoBulkIngestLocked(self: *ProvisionedTableWriteCache, group_id: u64, table_name: []const u8, now_ns: u64) !bool {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (!entry.auto_bulk_ingest_session_open or !entry.auto_bulk_ingest_finish_requested) return false;
            if (self.entryActiveLeasesLocked(entry) > 1) return false;
            try entry.db.rollPrimaryStoreAutoBulkIngestSessionWithOptions(auto_bulk_ingest_finish_options);
            entry.auto_bulk_ingest_session_open = true;
            entry.auto_bulk_ingest_ops = 0;
            entry.auto_bulk_ingest_started_ns = now_ns;
            entry.auto_bulk_ingest_last_ns = now_ns;
            entry.auto_bulk_ingest_finish_requested = false;
            return true;
        }
        return false;
    }

    pub fn finishAutoBulkIngestLocked(self: *ProvisionedTableWriteCache, group_id: u64, table_name: []const u8) !void {
        for (self.entries.items) |entry| {
            if (entry.group_id != group_id or !std.mem.eql(u8, entry.table_name, table_name) or !entry.auto_bulk_ingest_session_open) continue;
            try entry.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(auto_bulk_ingest_finish_options);
            entry.bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_session_open = false;
            entry.auto_bulk_ingest_ops = 0;
            entry.auto_bulk_ingest_started_ns = 0;
            entry.auto_bulk_ingest_last_ns = 0;
            entry.auto_bulk_ingest_finish_requested = false;
        }
        self.removeInactiveBulkIngestSessionLocked(table_name);
    }

    pub fn finishExpiredAutoBulkIngestLocked(self: *ProvisionedTableWriteCache, now_ns: u64) !bool {
        return self.finishExpiredAutoBulkIngestLockedWithStatusLeases(now_ns, std.heap.page_allocator, null);
    }

    fn finishExpiredAutoBulkIngestLockedWithStatusLeases(
        self: *ProvisionedTableWriteCache,
        now_ns: u64,
        lease_alloc: std.mem.Allocator,
        finished_leases: ?*std.ArrayListUnmanaged(CachedDb),
    ) !bool {
        var first_err: ?anyerror = null;
        var finished_any = false;
        for (self.entries.items) |entry| {
            if (!entry.auto_bulk_ingest_session_open) continue;
            if (self.entryActiveLeasesLocked(entry) != 0) continue;
            const idle_expired = entry.auto_bulk_ingest_last_ns > 0 and now_ns -| entry.auto_bulk_ingest_last_ns >= auto_bulk_ingest_max_idle_ns;
            if (!entry.auto_bulk_ingest_finish_requested and !idle_expired) continue;
            if (!idle_expired and entry.auto_bulk_ingest_finish_requested) {
                continue;
            } else {
                entry.db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(auto_bulk_ingest_finish_options) catch |err| {
                    if (first_err == null) first_err = err;
                    continue;
                };
                entry.bulk_ingest_session_open = false;
                entry.auto_bulk_ingest_session_open = false;
                entry.auto_bulk_ingest_ops = 0;
                entry.auto_bulk_ingest_started_ns = 0;
                entry.auto_bulk_ingest_last_ns = 0;
                entry.auto_bulk_ingest_finish_requested = false;
                self.removeInactiveBulkIngestSessionLocked(entry.table_name);
            }
            if (finished_leases) |leases| {
                self.appendRuntimeStatusLeaseForEntryLocked(lease_alloc, entry, leases) catch |err| {
                    if (first_err == null) first_err = err;
                    continue;
                };
            }
            finished_any = true;
        }
        if (first_err) |err| return err;
        return finished_any;
    }

    fn appendRuntimeStatusLeaseForEntryLocked(
        self: *ProvisionedTableWriteCache,
        alloc: std.mem.Allocator,
        entry: *Entry,
        out: *std.ArrayListUnmanaged(CachedDb),
    ) !void {
        lockAtomic(&self.entry_lifecycle_mutex);
        entry.active_leases += 1;
        self.entry_lifecycle_mutex.unlock();
        errdefer self.releaseEntry(entry);

        try out.append(alloc, .{
            .cache = self,
            .entry = entry,
            .db = &entry.db,
            .schema_json = entry.schema_json,
        });
    }

    fn leaseLsmMaintenanceEntryLocked(self: *ProvisionedTableWriteCache, comptime best_effort: bool) ?CachedDb {
        var best_entry: ?*Entry = null;
        var best_score: u64 = 0;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.hasActiveDenseBulkWork()) continue;
            const raw_score = if (best_effort) entry.db.lsmMaintenanceDebtHint() else entry.db.lsmMaintenanceScore();
            const score = if (raw_score != 0) raw_score else versionPinnedObsoleteScore(entry);
            if (score > best_score) {
                best_score = score;
                best_entry = entry;
            }
        }
        if (best_score == 0) return null;
        return self.leaseEntryLocked(best_entry.?);
    }

    fn versionPinnedObsoleteScore(entry: *Entry) u64 {
        const stats = entry.db.trySnapshotLsmMaintenanceStats() orelse return 0;
        return if (stats.obsolete_paths_pinned_by_versions != 0) 1 else 0;
    }

    fn leaseLsmObsoleteReclaimDueLocked(self: *ProvisionedTableWriteCache) ?CachedDb {
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.hasActiveDenseBulkWork()) continue;
            if (entry.db.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| {
                if (delay_ns == 0) return self.leaseEntryLocked(entry);
            }
        }
        return null;
    }

    fn leasePrimaryLsmObsoleteReclaimDueLocked(self: *ProvisionedTableWriteCache) ?CachedDb {
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.nextPrimaryLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| {
                if (delay_ns == 0) return self.leaseEntryLocked(entry);
            }
        }
        return null;
    }

    pub fn leaseLsmMaintenanceRoundLocked(self: *ProvisionedTableWriteCache) ?CachedDb {
        return self.leaseLsmMaintenanceEntryLocked(false);
    }

    pub fn leaseLsmMaintenanceRoundBestEffortLocked(self: *ProvisionedTableWriteCache) ?CachedDb {
        return self.leaseLsmMaintenanceEntryLocked(true);
    }

    pub fn maxLsmMaintenanceScoreLocked(self: *const ProvisionedTableWriteCache) u64 {
        var score: u64 = 0;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.hasActiveDenseBulkWork()) continue;
            const raw_score = entry.db.lsmMaintenanceDebtHint();
            score = @max(score, if (raw_score != 0) raw_score else versionPinnedObsoleteScore(entry));
        }
        return score;
    }

    pub fn maxPrimaryLsmMaintenanceScoreLocked(self: *const ProvisionedTableWriteCache) u64 {
        var score: u64 = 0;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            const raw_score = entry.db.primaryLsmMaintenanceDebtHint();
            const reclaim_score: u64 = if (raw_score == 0) blk: {
                if (entry.db.nextPrimaryLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| {
                    break :blk if (delay_ns == 0) @as(u64, 1) else @as(u64, 0);
                }
                break :blk 0;
            } else 0;
            score = @max(score, @max(raw_score, reclaim_score));
        }
        return score;
    }

    pub fn nextLsmMaintenanceWakeDelayNsLocked(self: *const ProvisionedTableWriteCache) ?u64 {
        var delay_ns: ?u64 = null;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.hasActiveDenseBulkWork()) continue;
            if (entry.db.nextLsmMaintenanceWakeDelayNsBestEffort()) |candidate| {
                delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
            }
        }
        return delay_ns;
    }

    pub fn nextPrimaryLsmMaintenanceWakeDelayNsLocked(self: *const ProvisionedTableWriteCache) ?u64 {
        var delay_ns: ?u64 = null;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            if (entry.db.nextPrimaryLsmMaintenanceWakeDelayNsBestEffort()) |candidate| {
                delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
            }
        }
        return delay_ns;
    }

    pub fn leasePrimaryLsmMaintenanceRoundBestEffortLocked(self: *ProvisionedTableWriteCache) ?CachedDb {
        var best_entry: ?*Entry = null;
        var best_score: u64 = 0;
        for (self.entries.items) |entry| {
            if (entry.bulk_ingest_session_open) continue;
            const score = entry.db.primaryLsmMaintenanceDebtHint();
            if (score > best_score) {
                best_score = score;
                best_entry = entry;
            }
        }
        if (best_score == 0) return null;
        return self.leaseEntryLocked(best_entry.?);
    }

    fn bulkIngestSessionActiveForTable(self: *const ProvisionedTableWriteCache, table_name: []const u8) bool {
        return self.findActiveBulkIngestSession(table_name) != null;
    }

    fn bulkIngestSessionOpenForTable(self: *const ProvisionedTableWriteCache, table_name: []const u8) bool {
        if (self.bulkIngestSessionActiveForTable(table_name)) return true;
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) return true;
        }
        return false;
    }

    fn removeInactiveBulkIngestSessionLocked(self: *ProvisionedTableWriteCache, table_name: []const u8) void {
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) return;
        }
        const idx = self.findActiveBulkIngestSession(table_name) orelse return;
        var removed = self.active_bulk_ingest_sessions.orderedRemove(idx);
        removed.deinit(self.alloc);
    }

    fn findActiveBulkIngestSession(self: *const ProvisionedTableWriteCache, table_name: []const u8) ?usize {
        for (self.active_bulk_ingest_sessions.items, 0..) |session, i| {
            if (std.mem.eql(u8, session.table_name, table_name)) return i;
        }
        return null;
    }

    fn evictOldestTable(self: *ProvisionedTableWriteCache) void {
        if (self.table_metadata.items.len == 0) return;
        const table_name = self.table_metadata.items[0].table_name;
        if (self.table_eviction_hook) |hook| hook.notify(self, table_name);
        self.removeDbEntriesForTable(table_name);
        var removed = self.table_metadata.orderedRemove(0);
        removed.deinit(self.alloc);
    }

    fn notifyTableEvictions(self: *ProvisionedTableWriteCache) void {
        const hook = self.table_eviction_hook orelse return;
        for (self.table_metadata.items) |metadata| hook.notify(self, metadata.table_name);
    }

    fn reserveDbEntryRetirementsForTableLocked(self: *ProvisionedTableWriteCache, table_name: []const u8) !void {
        var matching_entries: usize = 0;
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            matching_entries += 1;
        }
        try self.reserveLifecycleRetireCapacityLocked(matching_entries);
    }

    fn replaceTableMetadataLocked(
        self: *ProvisionedTableWriteCache,
        table_name: []const u8,
        indexes_json: []const u8,
        schema_json: []const u8,
    ) !void {
        const replace_index = blk: {
            for (self.table_metadata.items, 0..) |metadata, i| {
                if (std.mem.eql(u8, metadata.table_name, table_name)) break :blk i;
            }
            break :blk null;
        };
        if (replace_index == null) try self.table_metadata.ensureUnusedCapacity(self.alloc, 1);
        var replacement = try self.cloneTableMetadataAlloc(table_name, indexes_json, schema_json);
        errdefer replacement.deinit(self.alloc);

        if (replace_index) |i| {
            self.table_metadata.items[i].deinit(self.alloc);
            self.table_metadata.items[i] = replacement;
            return;
        }

        if (self.table_metadata.items.len >= max_cached_write_tables) self.evictOldestTable();
        self.table_metadata.appendAssumeCapacity(replacement);
    }

    fn replaceTableMetadataAndRetireEntriesLocked(
        self: *ProvisionedTableWriteCache,
        table_name: []const u8,
        indexes_json: []const u8,
        schema_json: []const u8,
    ) !void {
        try self.replaceTableMetadataLocked(table_name, indexes_json, schema_json);
        try self.retireDbEntriesForTableLocked(table_name);
    }

    fn installLoadedTableMetadataLocked(
        self: *ProvisionedTableWriteCache,
        cached_index: ?usize,
        replacement: TableMetadata,
    ) !*const TableMetadata {
        if (cached_index) |i| {
            if (!self.tableHasOnlyInactiveAdoptableEntriesLocked(replacement.table_name)) {
                try self.retireDbEntriesForTableLocked(replacement.table_name);
            }
            self.table_metadata.items[i].deinit(self.alloc);
            self.table_metadata.items[i] = replacement;
            return &self.table_metadata.items[i];
        }

        if (self.table_metadata.items.len >= max_cached_write_tables) self.evictOldestTable();
        self.table_metadata.appendAssumeCapacity(replacement);
        return &self.table_metadata.items[self.table_metadata.items.len - 1];
    }

    fn tableMetadataLocked(self: *const ProvisionedTableWriteCache, table_name: []const u8) ?TableMetadata {
        for (self.table_metadata.items) |metadata| {
            if (std.mem.eql(u8, metadata.table_name, table_name)) return metadata;
        }
        return null;
    }

    fn hasTableStateLocked(self: *const ProvisionedTableWriteCache, table_name: []const u8) bool {
        if (self.tableMetadataLocked(table_name) != null) return true;
        for (self.entries.items) |entry| {
            if (std.mem.eql(u8, entry.table_name, table_name)) return true;
        }
        return false;
    }

    fn tableHasOnlyInactiveAdoptableEntriesLocked(
        self: *const ProvisionedTableWriteCache,
        table_name: []const u8,
    ) bool {
        var found = false;
        for (self.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            found = true;
            if (!entry.allow_generation_adoption) return false;
            if (self.entryActiveLeasesLocked(entry) != 0) return false;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) return false;
        }
        return found;
    }

    fn transferAdoptableEntriesForTableLocked(
        self: *ProvisionedTableWriteCache,
        dest: *ProvisionedTableWriteCache,
        table_name: []const u8,
        generation_source: ?table_reads.GroupVisibleRootGenerationSource,
    ) !usize {
        if (self.alloc.ptr != dest.alloc.ptr or self.alloc.vtable != dest.alloc.vtable) {
            return self.retireAdoptableEntriesForTableLocked(table_name);
        }

        const metadata = self.tableMetadataLocked(table_name);
        if (metadata) |value| {
            if (value.indexes_json) |indexes_json| {
                try dest.replaceTableMetadataLocked(table_name, indexes_json, value.schema_json orelse "");
            }
        }

        var moved: usize = 0;
        var i: usize = 0;
        while (i < self.entries.items.len) {
            const entry = self.entries.items[i];
            if (!std.mem.eql(u8, entry.table_name, table_name)) {
                i += 1;
                continue;
            }
            if (!entry.allow_generation_adoption or self.entryActiveLeasesLocked(entry) != 0 or entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                i += 1;
                continue;
            }

            const dest_generation = if (generation_source) |source| source.visibleRootGenerationForGroup(entry.group_id) else table_reads.backend_current_root_generation;
            try dest.pruneStaleEntriesForGroupTableLocked(entry.group_id, dest_generation, table_name);
            var existing_index: ?usize = null;
            for (dest.entries.items, 0..) |dest_entry, dest_i| {
                if (dest_entry.group_id != entry.group_id) continue;
                if (!std.mem.eql(u8, dest_entry.table_name, table_name)) continue;
                existing_index = dest_i;
                break;
            }
            if (existing_index) |dest_i| {
                try dest.reserveLifecycleRetireCapacityLocked(1);
                const removed = dest.entries.orderedRemove(dest_i);
                dest.retireEntryLocked(removed);
            }

            try dest.reserveInstalledEntryLifecycleCapacityLocked(1);
            try dest.entries.ensureUnusedCapacity(dest.alloc, 1);
            _ = self.entries.orderedRemove(i);
            entry.lsm_root_generation = dest_generation;
            dest.entries.appendAssumeCapacity(entry);
            moved += 1;
        }
        return moved;
    }

    fn retireAdoptableEntriesForTableLocked(
        self: *ProvisionedTableWriteCache,
        table_name: []const u8,
    ) usize {
        var retired: usize = 0;
        var i: usize = 0;
        while (i < self.entries.items.len) {
            const entry = self.entries.items[i];
            if (!std.mem.eql(u8, entry.table_name, table_name) or
                !entry.allow_generation_adoption or
                self.entryActiveLeasesLocked(entry) != 0 or
                entry.bulk_ingest_session_open or
                entry.auto_bulk_ingest_session_open)
            {
                i += 1;
                continue;
            }

            self.reserveLifecycleRetireCapacityLocked(1) catch {
                i += 1;
                continue;
            };
            const removed = self.entries.orderedRemove(i);
            self.retireEntryLocked(removed);
            retired += 1;
        }
        return retired;
    }

    fn getOrLoadMetadataLocked(
        self: *ProvisionedTableWriteCache,
        catalog: table_catalog.CatalogSource,
        table_name: []const u8,
    ) !*const TableMetadata {
        var snapshot = try catalog.adminSnapshot();
        defer catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name);

        var cached_index: ?usize = null;
        for (self.table_metadata.items, 0..) |*metadata, i| {
            if (std.mem.eql(u8, metadata.table_name, table_name)) {
                cached_index = i;
                if (table) |current| {
                    const indexes_match = if (metadata.indexes_json) |cached|
                        std.mem.eql(u8, cached, current.indexes_json)
                    else
                        current.indexes_json.len == 0;
                    const schema_match = if (metadata.schema_json) |cached|
                        std.mem.eql(u8, cached, current.schema_json)
                    else
                        current.schema_json.len == 0;
                    if (indexes_match and schema_match) return metadata;
                } else if (metadata.indexes_json == null and metadata.schema_json == null) {
                    return metadata;
                }
                break;
            }
        }

        if (cached_index != null) {
            try self.reserveDbEntryRetirementsForTableLocked(table_name);
        } else {
            try self.table_metadata.ensureUnusedCapacity(self.alloc, 1);
        }

        const indexes_json = if (table) |current| current.indexes_json else null;
        const schema_json = if (table) |current| current.schema_json else null;
        var replacement = try self.cloneTableMetadataAlloc(table_name, indexes_json, schema_json);
        errdefer replacement.deinit(self.alloc);

        const installed = try self.installLoadedTableMetadataLocked(cached_index, replacement);
        replacement = undefined;
        return installed;
    }

    fn entryActiveLeasesLocked(self: *const ProvisionedTableWriteCache, entry: *const Entry) usize {
        lockAtomic(@constCast(&self.entry_lifecycle_mutex));
        defer @constCast(&self.entry_lifecycle_mutex).unlock();
        return entry.active_leases;
    }

    fn reserveLifecycleRetireCapacityLocked(self: *ProvisionedTableWriteCache, count: usize) !void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        try self.retired_entries.ensureUnusedCapacity(self.alloc, count);
        try self.closing_entries.ensureUnusedCapacity(self.alloc, count);
    }

    /// Every installed entry owns one preallocated slot in each retirement
    /// queue. Queue-to-queue moves preserve the total, so cache-wide retirement
    /// never allocates and HA ownership changes cannot fail after publication.
    fn reserveInstalledEntryLifecycleCapacityLocked(self: *ProvisionedTableWriteCache, additional_entries: usize) !void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        const queued = try std.math.add(usize, self.retired_entries.items.len, self.closing_entries.items.len);
        const installed = try std.math.add(usize, self.entries.items.len, additional_entries);
        const required = try std.math.add(usize, queued, installed);
        try self.retired_entries.ensureTotalCapacity(self.alloc, required);
        try self.closing_entries.ensureTotalCapacity(self.alloc, required);
    }

    fn retireEntryAssumeLifecycleLocked(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        if (entry.retired) return;
        entry.retired = true;
        if (entry.active_leases == 0) {
            self.queueEntryForCloseAssumeLifecycleLocked(entry);
            return;
        }
        self.retired_entries.append(self.alloc, entry) catch |err| {
            std.log.err("failed to queue retired writer-cache entry table={s} err={s}", .{ entry.table_name, @errorName(err) });
            @panic("failed to queue retired writer-cache entry");
        };
    }

    fn retireInactiveEntryAtIndexForCloseLocked(self: *ProvisionedTableWriteCache, index: usize) !bool {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        const entry = self.entries.items[index];
        if (entry.active_leases != 0) return false;
        try self.closing_entries.ensureUnusedCapacity(self.alloc, 1);
        _ = self.entries.orderedRemove(index);
        entry.retired = true;
        self.queueEntryForCloseAssumeLifecycleLocked(entry);
        return true;
    }

    fn releaseEntry(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        std.debug.assert(entry.active_leases > 0);
        entry.active_leases -= 1;
        if (entry.active_leases == 0 and entry.retired) {
            self.queueRetiredEntryForCloseLocked(entry) catch |err| {
                std.log.err("failed to queue retired writer-cache entry for close: {}", .{err});
            };
        }
    }

    fn retireEntryLocked(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        self.retireEntryAssumeLifecycleLocked(entry);
    }

    fn reserveRetiredEntriesCapacityLocked(self: *ProvisionedTableWriteCache, count: usize) !void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        try self.retired_entries.ensureUnusedCapacity(self.alloc, count);
    }

    fn markEntryRetiredUntrackedLocked(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        lockAtomic(&self.entry_lifecycle_mutex);
        defer self.entry_lifecycle_mutex.unlock();
        if (entry.retired) return;
        entry.retired = true;
    }

    fn queueRetiredEntryForCloseLocked(self: *ProvisionedTableWriteCache, entry: *Entry) !void {
        try self.closing_entries.ensureUnusedCapacity(self.alloc, 1);
        var i: usize = 0;
        while (i < self.retired_entries.items.len) : (i += 1) {
            if (self.retired_entries.items[i] != entry) continue;
            _ = self.retired_entries.orderedRemove(i);
            break;
        }
        self.queueEntryForCloseAssumeLifecycleLocked(entry);
    }

    fn queueEntryForCloseAssumeLifecycleLocked(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        if (entry.close_queued) return;
        entry.close_queued = true;
        self.closing_entries.append(self.alloc, entry) catch |err| {
            std.log.err("failed to queue retired writer-cache entry for close table={s} err={s}", .{ entry.table_name, @errorName(err) });
            @panic("failed to queue retired writer-cache entry for close");
        };
    }

    fn closeEntryNow(self: *ProvisionedTableWriteCache, entry: *Entry) void {
        entry.deinit(self.alloc);
        self.alloc.destroy(entry);
    }

    fn drainPendingClosesForGroupTableAssumeOpenMutexHeld(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) void {
        while (true) {
            var entry_to_close: ?*Entry = null;
            lockAtomic(&self.entry_lifecycle_mutex);
            var i: usize = 0;
            while (i < self.retired_entries.items.len) : (i += 1) {
                const entry = self.retired_entries.items[i];
                if (entry.group_id != group_id) continue;
                if (entry.active_leases != 0) continue;
                if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
                entry_to_close = self.retired_entries.orderedRemove(i);
                break;
            }
            if (entry_to_close == null) {
                i = 0;
                while (i < self.closing_entries.items.len) : (i += 1) {
                    const entry = self.closing_entries.items[i];
                    if (entry.group_id != group_id) continue;
                    if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
                    entry_to_close = self.closing_entries.orderedRemove(i);
                    break;
                }
            }
            self.entry_lifecycle_mutex.unlock();

            const entry = entry_to_close orelse return;
            self.closeEntryNow(entry);
        }
    }

    fn drainPendingClosesForGroupTable(
        self: *ProvisionedTableWriteCache,
        group_id: u64,
        table_name: []const u8,
    ) void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        self.drainPendingClosesForGroupTableAssumeOpenMutexHeld(group_id, table_name);
    }

    fn drainPendingClosesAssumeOpenMutexHeld(self: *ProvisionedTableWriteCache) void {
        while (true) {
            var entry_to_close: ?*Entry = null;
            lockAtomic(&self.entry_lifecycle_mutex);
            var i: usize = 0;
            while (i < self.retired_entries.items.len) : (i += 1) {
                const entry = self.retired_entries.items[i];
                if (entry.active_leases != 0) continue;
                entry_to_close = self.retired_entries.orderedRemove(i);
                break;
            }
            if (entry_to_close == null and self.closing_entries.items.len != 0) {
                entry_to_close = self.closing_entries.orderedRemove(0);
            }
            self.entry_lifecycle_mutex.unlock();

            const entry = entry_to_close orelse return;
            self.closeEntryNow(entry);
        }
    }

    fn drainPendingCloses(self: *ProvisionedTableWriteCache) void {
        lockAtomic(&self.open_mutex);
        defer self.open_mutex.unlock();
        self.drainPendingClosesAssumeOpenMutexHeld();
    }
};

const HostedManagedDbCache = struct {
    replica_root_dir: []u8,
    mutex: std.atomic.Mutex = .unlocked,
    write_cache: ProvisionedTableWriteCache,
    runtime_status_cache: runtime_status.TableRuntimeSnapshotCache,

    fn init(alloc: std.mem.Allocator, replica_root_dir: []const u8) !*HostedManagedDbCache {
        const cache = try alloc.create(HostedManagedDbCache);
        errdefer alloc.destroy(cache);
        cache.* = .{
            .replica_root_dir = try alloc.dupe(u8, replica_root_dir),
            .write_cache = ProvisionedTableWriteCache.init(alloc),
            .runtime_status_cache = runtime_status.TableRuntimeSnapshotCache.init(alloc),
        };
        return cache;
    }
};

pub const HostedManagedDbCacheDiagnostics = struct {
    present: bool = false,
    cached_roots: u64 = 0,
    cached_entries: u64 = 0,
    retired_entries: u64 = 0,
    table_metadata_entries: u64 = 0,
    active_bulk_sessions: u64 = 0,
    active_leases: u64 = 0,
    retired_active_leases: u64 = 0,
    bulk_ingest_open_entries: u64 = 0,
    auto_bulk_ingest_open_entries: u64 = 0,
    auto_bulk_ingest_finish_requested_entries: u64 = 0,
    lsm_mutable_bytes: u64 = 0,
    lsm_immutable_bytes: u64 = 0,
    lsm_total_run_bytes: u64 = 0,
    lsm_wal_retained_bytes: u64 = 0,
    lsm_wal_retained_segments: u64 = 0,
    lsm_active_readers: u64 = 0,
    lsm_obsolete_paths: u64 = 0,
    lsm_bulk_ingest_current_scan_clone_active_bytes: u64 = 0,
};

var hosted_managed_db_cache_registry_mutex: std.atomic.Mutex = .unlocked;
var hosted_managed_db_cache_registry: std.ArrayListUnmanaged(*HostedManagedDbCache) = .empty;

pub fn closeHostedManagedDbCacheForRoot(replica_root_dir: []const u8) void {
    const alloc = std.heap.page_allocator;
    var removed: ?*HostedManagedDbCache = null;
    lockAtomic(&hosted_managed_db_cache_registry_mutex);
    {
        defer hosted_managed_db_cache_registry_mutex.unlock();
        for (hosted_managed_db_cache_registry.items, 0..) |cache, idx| {
            if (!std.mem.eql(u8, cache.replica_root_dir, replica_root_dir)) continue;
            removed = hosted_managed_db_cache_registry.orderedRemove(idx);
            break;
        }
    }

    const cache = removed orelse return;
    lockAtomic(&cache.mutex);
    cache.write_cache.deinit();
    cache.runtime_status_cache.deinit();
    cache.mutex.unlock();
    alloc.free(cache.replica_root_dir);
    alloc.destroy(cache);
}

fn hostedManagedDbCacheForRoot(replica_root_dir: []const u8) !*HostedManagedDbCache {
    const alloc = std.heap.page_allocator;
    lockAtomic(&hosted_managed_db_cache_registry_mutex);
    defer hosted_managed_db_cache_registry_mutex.unlock();

    for (hosted_managed_db_cache_registry.items) |cache| {
        if (std.mem.eql(u8, cache.replica_root_dir, replica_root_dir)) return cache;
    }

    const cache = try HostedManagedDbCache.init(alloc, replica_root_dir);
    errdefer {
        alloc.free(cache.replica_root_dir);
        alloc.destroy(cache);
    }
    try hosted_managed_db_cache_registry.append(alloc, cache);
    return cache;
}

fn hostedManagedDbCacheForRootIfPresent(replica_root_dir: []const u8) ?*HostedManagedDbCache {
    lockAtomic(&hosted_managed_db_cache_registry_mutex);
    defer hosted_managed_db_cache_registry_mutex.unlock();

    for (hosted_managed_db_cache_registry.items) |cache| {
        if (std.mem.eql(u8, cache.replica_root_dir, replica_root_dir)) return cache;
    }
    return null;
}

pub fn hostedManagedDbCacheDiagnosticsForRoot(replica_root_dir: []const u8) HostedManagedDbCacheDiagnostics {
    lockAtomic(&hosted_managed_db_cache_registry_mutex);
    defer hosted_managed_db_cache_registry_mutex.unlock();
    const cached_roots: u64 = @intCast(hosted_managed_db_cache_registry.items.len);
    for (hosted_managed_db_cache_registry.items) |selected| {
        if (!std.mem.eql(u8, selected.replica_root_dir, replica_root_dir)) continue;
        lockAtomic(&selected.mutex);
        defer selected.mutex.unlock();
        const write_cache = selected.write_cache.diagnosticsLocked();
        return .{
            .present = true,
            .cached_roots = cached_roots,
            .cached_entries = write_cache.cached_entries,
            .retired_entries = write_cache.retired_entries,
            .table_metadata_entries = write_cache.table_metadata_entries,
            .active_bulk_sessions = write_cache.active_bulk_sessions,
            .active_leases = write_cache.active_leases,
            .retired_active_leases = write_cache.retired_active_leases,
            .bulk_ingest_open_entries = write_cache.bulk_ingest_open_entries,
            .auto_bulk_ingest_open_entries = write_cache.auto_bulk_ingest_open_entries,
            .auto_bulk_ingest_finish_requested_entries = write_cache.auto_bulk_ingest_finish_requested_entries,
            .lsm_mutable_bytes = write_cache.lsm_mutable_bytes,
            .lsm_immutable_bytes = write_cache.lsm_immutable_bytes,
            .lsm_total_run_bytes = write_cache.lsm_total_run_bytes,
            .lsm_wal_retained_bytes = write_cache.lsm_wal_retained_bytes,
            .lsm_wal_retained_segments = write_cache.lsm_wal_retained_segments,
            .lsm_active_readers = write_cache.lsm_active_readers,
            .lsm_obsolete_paths = write_cache.lsm_obsolete_paths,
            .lsm_bulk_ingest_current_scan_clone_active_bytes = write_cache.lsm_bulk_ingest_current_scan_clone_active_bytes,
        };
    }
    return .{ .cached_roots = cached_roots };
}

fn parseJsonBodyIgnoreUnknown(comptime T: type, alloc: std.mem.Allocator, body: []const u8) !std.json.Parsed(T) {
    return try std.json.parseFromSlice(T, alloc, body, .{ .ignore_unknown_fields = true });
}

fn jsonValueContainsText(value: std.json.Value, needle: []const u8) bool {
    switch (value) {
        .string => |text| return std.mem.indexOf(u8, text, needle) != null,
        .array => |items| {
            for (items.items) |item| {
                if (jsonValueContainsText(item, needle)) return true;
            }
            return false;
        },
        .object => |obj| {
            var it = obj.iterator();
            while (it.next()) |entry| {
                if (std.mem.indexOf(u8, entry.key_ptr.*, needle) != null) return true;
                if (jsonValueContainsText(entry.value_ptr.*, needle)) return true;
            }
            return false;
        },
        else => return false,
    }
}

const TestEmbeddingRequest = struct {
    model: std.json.Value,
    input: std.json.Value,
};

pub const TableWriteSource = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        create_table: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            req: tables_api.CreateTableRequest,
        ) anyerror!?void = null,
        update_schema: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            schema_json: []const u8,
        ) anyerror!?void = null,
        create_index: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            index_name: []const u8,
            index_json: []const u8,
        ) anyerror!?void = null,
        put_artifact_enrichment: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            artifact_name: []const u8,
            enrichment_json: []const u8,
        ) anyerror!?void = null,
        delete_artifact_enrichment: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            artifact_name: []const u8,
        ) anyerror!?void = null,
        drop_index: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
            index_name: []const u8,
        ) anyerror!?void = null,
        drop_table: ?*const fn (
            ptr: *anyopaque,
            alloc: std.mem.Allocator,
            table_name: []const u8,
