        if (!std.mem.eql(u8, self.table_name, table_name)) return null;
        const db = try self.activeDb();
        try validateTableBatchAgainstLocalSchema(alloc, db, req.writes, req.deletes, req.transforms);
        try db.batch(req);
    }

