    pub fn autoBulkIngestStatsBestEffort(self: *ProvisionedTableWriteSource) ProvisionedTableWriteCache.AutoBulkIngestStats {
        if (!self.local_db_mutex.tryLock()) return .{};
        defer self.local_db_mutex.unlock();
        const now_ns = platform_time.monotonicNs();
        var stats = ProvisionedTableWriteCache.AutoBulkIngestStats{};
        if (self.write_cache) |cache| stats.merge(cache.autoBulkIngestStatsLocked(now_ns));
        if (self.startup_write_cache) |cache| stats.merge(cache.autoBulkIngestStatsLocked(now_ns));
        return stats;
    }

    pub fn cachedWriteDbCount(self: *ProvisionedTableWriteSource) usize {
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return 0;
        return cache.entries.items.len;
    }

    pub fn cachedWriteDbCountBestEffort(self: *ProvisionedTableWriteSource) usize {
        if (!self.local_db_mutex.tryLock()) return 0;
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return 0;
        return cache.entries.items.len;
    }

    pub fn readPreparation(self: *ProvisionedTableWriteSource) table_reads.ReadPreparation {
        return .{
            .ptr = self,
            .vtable = &.{
                .prepare_for_read = prepareForRead,
                .begin_read = beginRead,
            },
        };
    }

    pub fn primaryLookupDbSource(self: *ProvisionedTableWriteSource) table_reads.PrimaryLookupDbSource {
        return .{
            .ptr = self,
            .lease_group = leasePrimaryLookupDb,
        };
    }

    fn prepareForRead(ptr: *anyopaque, table_name: []const u8, kind: table_reads.ReadPreparation.Kind) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| return prepareForRead(owner, table_name, kind);
        self.waitForNoReadBlockingActivity(table_name);
        if (!self.isWriteCacheDirtyForTable(table_name)) return;

        // Data writes and derived catch-up are intentionally eventually visible
        // to queries. A read can discard its cached reader and reopen the latest
        // published view, but it must not wait behind writer-cache maintenance
        // or close the live writer cache from the query path.
        self.invalidateReadCache(table_name);
        if (self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) return;
        self.clearDirtyWriteTable(table_name);
    }

    fn beginRead(ptr: *anyopaque, table_name: []const u8, kind: table_reads.ReadPreparation.Kind) table_reads.ReadPreparation.Activity {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| return beginRead(owner, table_name, kind);
        self.beginReadRequest(table_name);
        if (self.isWriteCacheDirtyForTable(table_name)) {
            self.invalidateReadCache(table_name);
            if (!self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) {
                self.clearDirtyWriteTable(table_name);
            }
        }
        return .{
            .ptr = self,
            .table_name = table_name,
            .release_fn = endRead,
        };
    }

    fn endRead(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.endReadRequest(table_name);
    }

    fn leasePrimaryLookupDb(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        lsm_root_generation: u64,
    ) !?table_reads.PrimaryLookupDbLease {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.local_write_owner) |owner| {
            return try leasePrimaryLookupDb(owner, alloc, table_name, group_id, lsm_root_generation);
        }
        self.beginReadRequest(table_name);
        var read_request_active = true;
        errdefer if (read_request_active) self.endReadRequest(table_name);

        lockAtomic(&self.local_db_mutex);
        var cached: ?ProvisionedTableWriteCache.CachedDb = null;
        if (self.write_cache) |cache| {
            cached = cache.snapshotLeaseOrAdoptSeededLocked(group_id, lsm_root_generation, table_name);
        }
        if (cached == null) {
            if (self.startup_write_cache) |cache| {
                cached = cache.snapshotLeaseOrAdoptSeededLocked(group_id, lsm_root_generation, table_name);
            }
        }
        self.local_db_mutex.unlock();

        var cached_value = cached orelse {
            self.endReadRequest(table_name);
            read_request_active = false;
            return null;
        };
        const owned_table_name = alloc.dupe(u8, table_name) catch |err| {
            cached_value.deinit(alloc);
            self.endReadRequest(table_name);
            read_request_active = false;
            return err;
        };
        errdefer alloc.free(owned_table_name);
        const lease_ctx = alloc.create(PrimaryLookupLeaseContext) catch |err| {
            cached_value.deinit(alloc);
            self.endReadRequest(table_name);
            read_request_active = false;
            return err;
        };
        lease_ctx.* = .{
            .source = self,
            .table_name = owned_table_name,
            .cached = cached_value,
        };
        read_request_active = false;
        return .{
            .ptr = lease_ctx,
            .db = lease_ctx.cached.db,
            .release_fn = releasePrimaryLookupDb,
        };
    }

    const PrimaryLookupLeaseContext = struct {
        source: *ProvisionedTableWriteSource,
        table_name: []u8,
        cached: ProvisionedTableWriteCache.CachedDb,
    };

    fn releasePrimaryLookupDb(ptr: *anyopaque, alloc: std.mem.Allocator) void {
        const lease_ctx: *PrimaryLookupLeaseContext = @ptrCast(@alignCast(ptr));
        lease_ctx.cached.deinit(alloc);
        lease_ctx.source.endReadRequest(lease_ctx.table_name);
        alloc.free(lease_ctx.table_name);
        alloc.destroy(lease_ctx);
    }

    fn hasDirtyWriteTableLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        return self.dirty_write_tables.contains(table_name);
    }

    fn publishDirtyWriteTableCountLocked(self: *ProvisionedTableWriteSource) void {
        const count = self.dirty_write_tables.count();
        self.dirty_write_table_count.store(@intCast(@min(count, std.math.maxInt(u32))), .release);
    }

    fn isWriteCacheDirtyForTable(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.local_write_owner) |owner| return owner.isWriteCacheDirtyForTable(table_name);
        if (self.dirty_write_table_count.load(.acquire) == 0) return false;
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        return self.hasDirtyWriteTableLocked(table_name);
    }

    fn clearAllDirtyWriteTablesLocked(self: *ProvisionedTableWriteSource) void {
        var keys = self.dirty_write_tables.keyIterator();
        while (keys.next()) |table_name| std.heap.page_allocator.free(table_name.*);
        self.dirty_write_tables.clearRetainingCapacity();
        self.dirty_write_table_count.store(0, .release);
    }

    fn clearAllDirtyWriteTables(self: *ProvisionedTableWriteSource) void {
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        self.clearAllDirtyWriteTablesLocked();
    }

    fn clearDirtyWriteTable(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.local_write_owner) |owner| return owner.clearDirtyWriteTable(table_name);
        lockAtomic(&self.dirty_write_tables_mutex);
        defer self.dirty_write_tables_mutex.unlock();
        if (self.dirty_write_tables.fetchRemove(table_name)) |removed| {
            std.heap.page_allocator.free(removed.key);
        }
        self.publishDirtyWriteTableCountLocked();
    }

    fn hasDirtyWriteTableWithLocalDbLocked(self: *ProvisionedTableWriteSource, table_name: []const u8) bool {
        if (self.dirty_write_table_count.load(.acquire) == 0) return false;
        const dirty = dirty_blk: {
            lockAtomic(&self.dirty_write_tables_mutex);
            defer self.dirty_write_tables_mutex.unlock();
            break :dirty_blk self.hasDirtyWriteTableLocked(table_name);
        };
        if (!dirty) return false;

        const cache = self.write_cache orelse {
            self.clearDirtyWriteTable(table_name);
            return false;
        };
        if (cache.bulkIngestSessionOpenForTable(table_name)) return true;
        if (cache.hasLiveEntryForTableLocked(table_name)) return true;

        self.clearDirtyWriteTable(table_name);
        return false;
    }

    fn markWriteCacheDirty(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        if (self.local_write_owner) |owner| return owner.markWriteCacheDirty(table_name);
        if (self.write_cache == null) return;
        lockAtomic(&self.dirty_write_tables_mutex);
        if (self.hasDirtyWriteTableLocked(table_name)) {
            self.dirty_write_tables_mutex.unlock();
            return;
        }
        // Own the name until successful publication/invalidation clears it.
        // This allocation happens once per clean-to-dirty transition, while
        // repeated writes to an already dirty table remain allocation-free.
        const owned_table_name = std.heap.page_allocator.dupe(u8, table_name) catch
            @panic("out of memory tracking dirty write tables");
        self.dirty_write_tables.put(std.heap.page_allocator, owned_table_name, {}) catch {
            std.heap.page_allocator.free(owned_table_name);
            @panic("out of memory tracking dirty write tables");
        };
        self.publishDirtyWriteTableCountLocked();
        self.dirty_write_tables_mutex.unlock();
    }

    fn invalidateDirtyWriteCacheForRead(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.dirty_write_tables_mutex);
        const dirty = self.hasDirtyWriteTableLocked(table_name);
        self.dirty_write_tables_mutex.unlock();
        if (!dirty) return;
        self.invalidateWriteCache(table_name);
    }

    fn notifyLocalChange(self: *ProvisionedTableWriteSource, table_name: []const u8, kind: LocalChangeKind) void {
        if (self.local_change_hook) |hook| hook.on_change(hook.ptr, table_name, kind);
    }

    fn changeKindForHARecord(record: db_mod.HAReplicationRecordView) LocalChangeKind {
        return switch (record.kind) {
            .metadata_mutation => .structural,
            else => .data,
        };
    }

    fn publishRestoreRepairComplete(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        self.invalidateReadCache(table_name);
        self.invalidateWriteCacheForTable(table_name);
        self.clearDirtyWriteTable(table_name);
        self.notifyLocalChange(table_name, .data);
    }

    fn enqueueRestoreRepairComplete(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        const alloc = std.heap.page_allocator;
        const owned_table_name = alloc.dupe(u8, table_name) catch |err| {
            std.log.warn("restore repair completion allocation failed table={s} err={}", .{ table_name, err });
            return;
        };

        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_mutex.lockUncancelable(io);
        self.restore_repair_completions.append(alloc, owned_table_name) catch |err| {
            self.restore_repair_completion_mutex.unlock(io);
            alloc.free(owned_table_name);
            std.log.warn("restore repair completion enqueue failed table={s} err={}", .{ table_name, err });
            return;
        };
        self.restore_repair_completion_mutex.unlock(io);
        self.scheduleRestoreRepairCompletionDrain();
    }

    fn scheduleRestoreRepairCompletionDrain(self: *ProvisionedTableWriteSource) void {
        if (self.restore_repair_completion_scheduled.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_group.concurrent(io, drainRestoreRepairCompletionsTask, .{self}) catch |err| {
            self.restore_repair_completion_scheduled.store(false, .release);
            std.log.warn("restore repair completion drain schedule failed err={}", .{err});
        };
    }

    fn drainRestoreRepairCompletionsTask(self: *ProvisionedTableWriteSource) !void {
        self.drainRestoreRepairCompletionsScheduled();
    }

    fn drainRestoreRepairCompletionsScheduled(self: *ProvisionedTableWriteSource) void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        while (true) {
            self.restore_repair_completion_mutex.lockUncancelable(io);
            if (self.restore_repair_completions.items.len == 0) {
                self.restore_repair_completion_scheduled.store(false, .release);
                self.restore_repair_completion_mutex.unlock(io);
                return;
            }
            var pending = self.restore_repair_completions;
            self.restore_repair_completions = .empty;
            self.restore_repair_completion_mutex.unlock(io);

            for (pending.items) |table_name| {
                self.publishRestoreRepairComplete(table_name);
                alloc.free(table_name);
            }
            pending.deinit(alloc);
        }
    }

    fn freeRestoreRepairCompletions(self: *ProvisionedTableWriteSource) void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        self.restore_repair_completion_mutex.lockUncancelable(io);
        defer self.restore_repair_completion_mutex.unlock(io);
        for (self.restore_repair_completions.items) |table_name| alloc.free(table_name);
        self.restore_repair_completions.deinit(alloc);
        self.restore_repair_completions = .empty;
    }

    fn openRestoreRepairDbForGroup(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        indexes_json: []const u8,
        staged_generation: ?*const db_mod.generation_lifecycle.StagedGeneration,
    ) !db_mod.DB {
        const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
        var db = try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
            alloc,
            path,
            indexes_json,
            null,
            null,
            self.visibleRootGeneration(group_id),
            null,
            .restore_repair,
            self.backend_runtime,
            self.antfly_provider,
            self.secret_store,
            self.remote_content,
            identity_namespace,
            .{ .staged_generation = staged_generation },
        );
        errdefer db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
        return db;
    }

    fn repairRestoredTableRuntimeStateBlocking(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        path: []const u8,
        group_id: u64,
        table_name: []const u8,
        indexes_json_override: ?[]const u8,
        schema_json_override: ?[]const u8,
        staged_generation: ?*const db_mod.generation_lifecycle.StagedGeneration,
    ) !void {
        const open_retry_timeout_ns = 2 * std.time.ns_per_s;
        const open_start_ns = platform_time.monotonicNs();
        var open_attempts: usize = 0;
        var logged_open_wait = false;
        while (true) {
            if (!try db_mod.DB.restoreRuntimeRepairNeededForPath(alloc, path)) return;

            const owned_indexes_json = if (indexes_json_override == null)
                (try loadTableIndexesJson(alloc, self.catalog, table_name)) orelse return error.TableVisibilityTimeout
            else
                null;
            defer if (owned_indexes_json) |value| alloc.free(value);
            const indexes_json = indexes_json_override orelse owned_indexes_json.?;

            open_attempts += 1;
            var db = self.openRestoreRepairDbForGroup(
                alloc,
                path,
                group_id,
                table_name,
                indexes_json,
                staged_generation,
            ) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked => {
                    if (platform_time.monotonicNs() -| open_start_ns >= open_retry_timeout_ns) return err;
                    if (!logged_open_wait) {
                        logged_open_wait = true;
                        std.log.warn("restore foreground repair waiting for writer table={s} group_id={d} err={s}", .{
                            table_name,
                            group_id,
                            @errorName(err),
                        });
                    }
                    self.table_activity_threaded.io().sleep(Io.Duration.fromNanoseconds(replicated_apply_writer_open_retry_ns), .awake) catch |sleep_err| switch (sleep_err) {
                        error.Canceled => Io.recancel(self.table_activity_threaded.io()),
                    };
                    continue;
                },
                else => return err,
            };
            defer db.close();

            if (schema_json_override) |schema_json| {
                try applyLocalTableSchemaJson(alloc, &db, schema_json);
            }

            const timeout_ns = 30 * std.time.ns_per_s;
            const start_ns = platform_time.monotonicNs();
            var attempts: usize = 0;
            std.log.info("restore foreground repair begin table={s} group_id={d}", .{ table_name, group_id });
            while (try db.restoreRuntimeRepairNeeded()) {
                attempts += 1;
                if (try db.repairRestoreRuntimeStateStepIfNeeded(alloc)) {
                    db.clearDenseHbcCaches();
                }
                if (platform_time.monotonicNs() -| start_ns >= timeout_ns) return error.TableVisibilityTimeout;
            }
            std.log.info("restore foreground repair complete table={s} group_id={d} attempts={d} open_attempts={d}", .{
                table_name,
                group_id,
                attempts,
                open_attempts,
            });
            return;
        }
    }

    const RestoreRepairCatchUpWork = struct {
        alloc: std.mem.Allocator,
        source: *ProvisionedTableWriteSource,
        group_id: u64,
        table_name: []u8,

        fn sleepRetry(self: *@This()) void {
            runTestBeforeRestoreRepairRetrySleepHook();
            self.source.table_activity_threaded.io().sleep(Io.Duration.fromMilliseconds(100), .awake) catch |err| switch (err) {
                error.Canceled => Io.recancel(self.source.table_activity_threaded.io()),
            };
        }

        fn runAndDeinit(work: *@This()) Io.Cancelable!void {
            defer RestoreRepairCatchUpWork.deinit(work);
            work.run() catch |err| {
                std.log.warn("restore background catch-up failed table={s} group_id={d} err={s}", .{
                    work.table_name,
                    work.group_id,
                    @errorName(err),
                });
            };
        }

        fn run(work: *@This()) !void {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(work.alloc, work.source.replica_root_dir, work.group_id);
            defer work.alloc.free(path);

            var attempts: usize = 0;
            std.log.info("restore background catch-up begin table={s} group_id={d}", .{ work.table_name, work.group_id });
            while (true) {
                if (work.source.restore_repair_shutdown.load(.acquire)) return;
                attempts += 1;
                const busy = try work.repairOnce(path);
                if (!busy) {
                    work.source.enqueueRestoreRepairComplete(work.table_name);
                    std.log.info("restore background catch-up complete table={s} group_id={d} attempts={d}", .{
                        work.table_name,
                        work.group_id,
                        attempts,
                    });
                    return;
                }
                work.sleepRetry();
            }
        }

        fn repairOnce(self: *@This(), path: []const u8) !bool {
            if (!self.source.tryBeginStructuralTableActivity(self.table_name)) return true;
            defer self.source.endStructuralTableActivity(self.table_name);
            var read_cache_exclusive = try self.source.beginReadCacheExclusive(self.table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            if (!try db_mod.DB.restoreRuntimeRepairNeededForPath(self.alloc, path)) return false;

            if (!self.source.local_db_mutex.tryLock()) return true;
            if (self.source.hasDirtyWriteTableWithLocalDbLocked(self.table_name)) {
                self.source.local_db_mutex.unlock();
                return true;
            }
            if (self.source.write_cache) |cache| {
                if (cache.hasForegroundStateForGroupTableLocked(self.group_id, self.table_name)) {
                    self.source.local_db_mutex.unlock();
                    return true;
                }
            }
            self.source.local_db_mutex.unlock();

            const indexes_json = (try loadTableIndexesJson(self.alloc, self.source.catalog, self.table_name)) orelse return true;
            defer self.alloc.free(indexes_json);

            var db = self.source.openRestoreRepairDbForGroup(
                self.alloc,
                path,
                self.group_id,
                self.table_name,
                indexes_json,
                null,
            ) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked => return true,
                else => return err,
            };
            defer db.close();

            if (try db.repairRestoreRuntimeStateStepIfNeeded(self.alloc)) {
                db.clearDenseHbcCaches();
            }
            return try db.restoreRuntimeRepairNeeded();
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            const alloc = work.alloc;
            alloc.free(work.table_name);
            alloc.destroy(work);
        }
    };

    fn requestRestoreRepairCatchUp(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) void {
        if (self.restore_repair_shutdown.load(.acquire)) return;
        const alloc = std.heap.page_allocator;
        const work = alloc.create(RestoreRepairCatchUpWork) catch |err| {
            std.log.warn("restore background catch-up allocation failed table={s} group_id={d} err={}", .{ table_name, group_id, err });
            return;
        };
        const owned_table_name = alloc.dupe(u8, table_name) catch |err| {
            alloc.destroy(work);
            std.log.warn("restore background catch-up table name allocation failed table={s} group_id={d} err={}", .{ table_name, group_id, err });
            return;
        };
        work.* = .{
            .alloc = alloc,
            .source = self,
            .group_id = group_id,
            .table_name = owned_table_name,
        };
        self.restore_repair_work_group.concurrent(self.table_activity_threaded.io(), RestoreRepairCatchUpWork.runAndDeinit, .{work}) catch |err| {
            RestoreRepairCatchUpWork.deinit(work);
            std.log.warn("restore background catch-up submit failed table={s} group_id={d} err={}", .{ table_name, group_id, err });
            return;
        };
    }

    fn freeStructuralReconcileTables(self: *ProvisionedTableWriteSource) void {
        const io = self.table_activity_threaded.io();
        const alloc = std.heap.page_allocator;
        self.structural_reconcile_mutex.lockUncancelable(io);
        defer self.structural_reconcile_mutex.unlock(io);
        for (self.structural_reconcile_tables.items) |*request| {
            self.cancelStructuralReconcileReservation(request.table_name);
            request.deinit(alloc);
        }
        self.structural_reconcile_tables.deinit(alloc);
        self.structural_reconcile_tables = .empty;
    }

    fn enqueueTableStructuralReconcile(self: *ProvisionedTableWriteSource, table_name: []const u8) !void {
        try self.enqueueTableStructuralReconcileTarget(table_name, null);
    }

    fn enqueueTableIndexStructuralReconcile(self: *ProvisionedTableWriteSource, table_name: []const u8, index_name: []const u8) !void {
        try self.enqueueTableStructuralReconcileTarget(table_name, index_name);
    }

    fn enqueueTableStructuralReconcileTarget(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        index_name: ?[]const u8,
    ) !void {
        if (self.restore_repair_shutdown.load(.acquire)) return error.BackgroundOwnerClosing;
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();

        self.structural_reconcile_mutex.lockUncancelable(io);
        defer self.structural_reconcile_mutex.unlock(io);

        for (self.structural_reconcile_tables.items) |candidate| {
            if (candidate.covers(table_name, index_name) or candidate.sameTarget(table_name, index_name)) return;
        }

        if (index_name == null) {
            var i: usize = 0;
            while (i < self.structural_reconcile_tables.items.len) {
                if (std.mem.eql(u8, self.structural_reconcile_tables.items[i].table_name, table_name)) {
                    var removed = self.structural_reconcile_tables.orderedRemove(i);
                    self.cancelStructuralReconcileReservation(removed.table_name);
                    removed.deinit(alloc);
                    continue;
                }
                i += 1;
            }
        }

        const owned_table_name = try alloc.dupe(u8, table_name);
        errdefer alloc.free(owned_table_name);
        const owned_index_name = if (index_name) |name| try alloc.dupe(u8, name) else null;
        errdefer if (owned_index_name) |name| alloc.free(name);
        const appended_index = self.structural_reconcile_tables.items.len;
        try self.structural_reconcile_tables.append(alloc, .{
            .table_name = owned_table_name,
            .index_name = owned_index_name,
        });
        self.reserveStructuralReconcileActivity(table_name);

        if (self.structural_reconcile_scheduled.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        self.restore_repair_work_group.concurrent(io, drainStructuralReconcileTask, .{self}) catch |err| {
            var removed = self.structural_reconcile_tables.orderedRemove(appended_index);
            self.cancelStructuralReconcileReservation(removed.table_name);
            removed.deinit(alloc);
            self.structural_reconcile_scheduled.store(false, .release);
            return err;
        };
    }

    fn drainStructuralReconcileTask(self: *ProvisionedTableWriteSource) Io.Cancelable!void {
        const alloc = std.heap.page_allocator;
        const io = self.table_activity_threaded.io();
        while (true) {
            self.structural_reconcile_mutex.lockUncancelable(io);
            if (self.structural_reconcile_tables.items.len == 0) {
                self.structural_reconcile_scheduled.store(false, .release);
                self.structural_reconcile_mutex.unlock(io);
                return;
            }
            var pending = self.structural_reconcile_tables;
            self.structural_reconcile_tables = .empty;
            self.structural_reconcile_mutex.unlock(io);
            var next_request: usize = 0;
            defer {
                for (pending.items[next_request..]) |*request| {
                    self.cancelStructuralReconcileReservation(request.table_name);
                    request.deinit(alloc);
                }
                pending.deinit(alloc);
            }

            while (next_request < pending.items.len) : (next_request += 1) {
                const request = &pending.items[next_request];
                self.beginReservedStructuralReconcileActivity(request.table_name);
                self.reconcileTableStructureUntilIdle(alloc, request.table_name, request.index_name) catch |err| {
                    if (request.index_name) |index_name| {
                        std.log.warn("structural reconcile failed table={s} index={s} err={s}", .{ request.table_name, index_name, @errorName(err) });
                    } else {
                        std.log.warn("structural reconcile failed table={s} err={s}", .{ request.table_name, @errorName(err) });
                    }
                };
                self.endStructuralReconcileActivity(request.table_name);
                request.deinit(alloc);
            }
        }
    }

    fn reconcileTableStructureUntilIdle(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        target_index_name: ?[]const u8,
    ) !void {
        const io = self.table_activity_threaded.io();
        if (target_index_name) |index_name| {
            std.log.info("structural reconcile begin table={s} index={s}", .{ table_name, index_name });
        } else {
            std.log.info("structural reconcile begin table={s}", .{table_name});
        }
        lockAtomic(&self.local_db_mutex);
        self.invalidateWriteCache(table_name);
        self.invalidateReadCache(table_name);
        self.invalidateRuntimeStatusCache(table_name);
        self.local_db_mutex.unlock();
        self.drainWriteCachePendingCloses();
        var attempts: usize = 0;
        while (true) {
            if (self.restore_repair_shutdown.load(.acquire)) return;
            attempts += 1;
            var any_busy = false;
            const group_ids = try table_catalog.resolveGroupsForSpanEventually(
                alloc,
                self.catalog,
                table_name,
                "",
                "",
                5 * std.time.ns_per_s,
                10,
            );
            defer alloc.free(group_ids);
            if (group_ids.len == 0) return;
            const metadata = (try loadTableManagedMetadata(alloc, self.catalog, table_name)) orelse return;
            defer {
                if (metadata.indexes_json) |value| alloc.free(value);
                if (metadata.schema_json) |value| alloc.free(value);
            }
            for (group_ids) |group_id| {
                if (try self.reconcileTableGroupStructureWithRuntime(alloc, group_id, table_name, .{
                    .indexes_json = metadata.indexes_json,
                    .schema_json = metadata.schema_json,
                    .target_index_name = target_index_name,
                })) {
                    any_busy = true;
                    continue;
                }
            }
            if (!any_busy) {
                // The reconciler mutated the current root in place and has
                // already published a consistent runtime snapshot. Rotating
                // the visible root generation here would immediately make
                // that snapshot stale and retire the writer that produced it.
                self.notifyLocalChange(table_name, .runtime_reconciled);
                if (target_index_name) |index_name| {
                    std.log.info("structural reconcile complete table={s} index={s} attempts={d}", .{ table_name, index_name, attempts });
                } else {
                    std.log.info("structural reconcile complete table={s} attempts={d}", .{ table_name, attempts });
                }
                return;
            }
            io.sleep(Io.Duration.fromMilliseconds(100), .awake) catch |err| switch (err) {
                error.Canceled => return Io.recancel(io),
            };
        }
    }

    fn reconcileTableGroupStructureWithRuntime(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        metadata: StartupCatchUpMetadata,
    ) !bool {
        if (!self.tryBeginGroupOperation(table_name, group_id)) return true;
        defer self.endGroupOperation(table_name, group_id);

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const lsm_root_generation = self.visibleRootGeneration(group_id);
        const identity_namespace = metadata.identity_namespace orelse
            try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);

        var configured_indexes_storage: ?StartupConfiguredIndexes = null;
        if (metadata.indexes_json) |value| configured_indexes_storage = try parseStartupConfiguredIndexes(alloc, value);
        defer if (configured_indexes_storage) |*summary| summary.deinit(alloc);

        if (self.write_cache) |cache| {
            var cached = self.getOrOpenCachedDbModeAtGeneration(alloc, cache, path, group_id, lsm_root_generation, table_name, .default_async, null, null, .{
                .indexes_json = metadata.indexes_json,
                .schema_json = metadata.schema_json,
                .identity_namespace = identity_namespace,
            }) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked => return true,
                else => return err,
            };
            var cached_active = true;
            defer if (cached_active) cached.deinit(alloc);

            if (metadata.schema_json) |schema_json| try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
            if (configured_indexes_storage) |configured_indexes| {
                if (metadata.target_index_name) |target_index_name| {
                    _ = cached.db.deleteIndex(target_index_name) catch |err| switch (err) {
                        error.IndexNotFound => {},
                        else => return err,
                    };
                } else {
                    for (configured_indexes.items) |item| {
                        _ = cached.db.deleteIndex(item.name) catch |err| switch (err) {
                            error.IndexNotFound => {},
                            else => return err,
                        };
                    }
                }
            }
            if (metadata.indexes_json) |indexes_json| {
                _ = try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, cached.db, indexes_json, .{
                    .drain_resolver_backfill = false,
                });
            }
            if (configured_indexes_storage) |configured_indexes| {
                for (configured_indexes.items) |item| {
                    if (metadata.target_index_name) |target_index_name| {
                        if (!std.mem.eql(u8, item.name, target_index_name)) continue;
                    }
                    catchUpManagedIndexCreate(alloc, cached.db, item.name) catch |err| {
                        lockAtomic(&self.local_db_mutex);
                        defer self.local_db_mutex.unlock();
                        cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                        cached_active = false;
                        return err;
                    };
                }
            } else {
                cached.db.runUntilIdle() catch |err| {
                    lockAtomic(&self.local_db_mutex);
                    defer self.local_db_mutex.unlock();
                    cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                    cached_active = false;
                    return err;
                };
            }
            publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, cached.db) catch |err| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                cache.retireCachedLeaseAfterMutationFailureLocked(&cached);
                cached_active = false;
                return err;
            };
            cache.publishCachedLeaseGeneration(&cached, lsm_root_generation);
            return false;
        }

        var db = if (metadata.indexes_json) |indexes_json|
            openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                alloc,
                path,
                indexes_json,
                null,
                null,
                lsm_root_generation,
                null,
                .default_async,
                self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                self.remote_content,
                identity_namespace,
                .{
                    .drain_resolver_backfill = false,
                    .inference_api_url = self.inference_api_url,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = self.ha_async_mirror,
                    .ha_async_batch_mirror = self.ha_async_mirror,
                    .ha_async_metadata_mirror = self.ha_async_mirror,
                },
            ) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked => return true,
                else => return err,
            }
        else
            db_mod.DB.open(alloc, path, .{
                .open_mode = .writer_no_replay,
                .lsm_root_generation = lsm_root_generation,
                .backend_runtime = self.backend_runtime,
                .identity_namespace = identity_namespace,
                .prefer_existing_identity_namespace = identity_namespace != null,
                .ha_write_gate = self.ha_write_gate,
                .ha_async_effect_mirror = self.ha_async_mirror,
                .ha_async_batch_mirror = self.ha_async_mirror,
                .ha_async_metadata_mirror = self.ha_async_mirror,
            }) catch |err| switch (err) {
                error.LsmRootWriterAlreadyOpen, error.WriterLocked => return true,
                else => return err,
            };
        defer db.close();
        try validateProvisionedDbIdentityNamespaceExpected(identity_namespace, &db);
        if (metadata.schema_json) |schema_json| try applyLocalTableSchemaJson(alloc, &db, schema_json);
        if (configured_indexes_storage) |configured_indexes| {
            if (metadata.target_index_name) |target_index_name| {
                _ = db.deleteIndex(target_index_name) catch |err| switch (err) {
                    error.IndexNotFound => {},
                    else => return err,
                };
            } else {
                for (configured_indexes.items) |item| {
                    _ = db.deleteIndex(item.name) catch |err| switch (err) {
                        error.IndexNotFound => {},
                        else => return err,
                    };
                }
            }
        }
        if (metadata.indexes_json) |indexes_json| {
            _ = try metadata_table_provisioner.reconcileDbIndexesWithOptions(alloc, &db, indexes_json, .{
                .drain_resolver_backfill = false,
            });
        }
        if (configured_indexes_storage) |configured_indexes| {
            for (configured_indexes.items) |item| {
                if (metadata.target_index_name) |target_index_name| {
                    if (!std.mem.eql(u8, item.name, target_index_name)) continue;
                }
                try catchUpManagedIndexCreate(alloc, &db, item.name);
            }
        } else {
            try db.runUntilIdle();
        }
        try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, &db);
        return false;
    }

    fn requestTableStructuralReconcile(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.requestTableStructuralReconcile(std.heap.page_allocator, table_name);
        try self.enqueueTableStructuralReconcile(table_name);
        return {};
    }

    fn requestTableIndexStructuralReconcile(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.requestTableIndexStructuralReconcile(std.heap.page_allocator, table_name, index_name);
        try self.enqueueTableIndexStructuralReconcile(table_name, index_name);
        return {};
    }

    fn beginBulkIngest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.beginBulkIngest(alloc, table_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;
        try cache.beginBulkIngestLocked(table_name);
    }

    fn finishBulkIngest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        options: backend_types.BulkIngestFinishOptions,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.finishBulkIngest(alloc, table_name, options);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return null;
        try cache.finishBulkIngestLocked(table_name, options);
    }

    fn abortBulkIngest(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            owner.abortBulkIngest(table_name);
            return;
        }
        lockAtomic(&self.local_db_mutex);
        defer self.local_db_mutex.unlock();
        const cache = self.write_cache orelse return;
        cache.abortBulkIngestLocked(table_name);
    }

    pub fn source(self: *ProvisionedTableWriteSource) TableWriteSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .create_table = createTable,
                .update_schema = updateSchema,
                .create_index = createIndex,
                .put_artifact_enrichment = putArtifactEnrichment,
                .delete_artifact_enrichment = deleteArtifactEnrichment,
                .drop_index = dropIndex,
                .drop_table = dropTable,
                .commit_transaction = commitTransaction,
                .commit_transaction_with_id = commitTransactionWithId,
                .backup_table = backupTable,
                .restore_table = restoreTable,
                .begin_restore_lifecycle = beginRestoreLifecycle,
                .finish_restore_lifecycle = finishRestoreLifecycle,
                .batch = batch,
                .begin_bulk_ingest = beginBulkIngest,
                .finish_bulk_ingest = finishBulkIngest,
                .abort_bulk_ingest = abortBulkIngest,
                .batch_group_local = batchGroupLocal,
                .txn_begin_group_local = txnBeginGroupLocal,
                .txn_prepare_group_local = txnPrepareGroupLocal,
                .txn_resolve_group_local = txnResolveGroupLocal,
                .txn_status_group_local = txnStatusGroupLocal,
                .corrupt_embedding_artifact = corruptEmbeddingArtifact,
                .reprocess_document_artifact = reprocessDocumentArtifact,
                .reprocess_document_artifact_range = reprocessDocumentArtifactRange,
                .list_artifact_repair_issues = listArtifactRepairIssues,
                .repair_artifact_issues = repairArtifactIssues,
                .repair_artifact_issues_controlled = repairArtifactIssuesControlled,
                .update_document_artifact_child_range_placement = updateDocumentArtifactChildRangePlacement,
                .apply_document_artifact_child_range_batch = applyDocumentArtifactChildRangeBatch,
                .reprocess_document_artifact_group_local = reprocessDocumentArtifactGroupLocal,
                .reprocess_document_artifact_range_group_local = reprocessDocumentArtifactRangeGroupLocal,
                .list_artifact_repair_issues_group_local = listArtifactRepairIssuesGroupLocal,
                .repair_artifact_issues_group_local = repairArtifactIssuesGroupLocal,
                .repair_artifact_issues_group_local_controlled = repairArtifactIssuesGroupLocalControlled,
                .update_document_artifact_child_range_placement_group_local = updateDocumentArtifactChildRangePlacementGroupLocal,
                .apply_document_artifact_child_range_batch_group_local = applyDocumentArtifactChildRangeBatchGroupLocal,
                .local_runtime_statuses = localRuntimeStatuses,
                .request_table_structural_reconcile = requestTableStructuralReconcile,
                .request_table_index_structural_reconcile = requestTableIndexStructuralReconcile,
            },
        };
    }

    fn putArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        enrichment_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.putArtifactEnrichment(alloc, table_name, artifact_name, enrichment_json);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (self.write_cache != null) {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);
            try putCachedLocalArtifactEnrichment(self, alloc, table_name, artifact_name, enrichment_json);
            self.finishLocalStructuralCachedDbMutation(table_name);
        } else {
            self.beginLocalStructuralCacheUpdate(table_name);
            errdefer self.abortLocalStructuralCacheUpdate(table_name);
            try putLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name, enrichment_json);
            self.finishLocalStructuralCacheUpdate(table_name);
        }
        self.notifyLocalChange(table_name, .structural);
    }

    fn deleteArtifactEnrichment(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.deleteArtifactEnrichment(alloc, table_name, artifact_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (self.write_cache != null) {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);
            try dropCachedLocalArtifactEnrichment(self, alloc, table_name, artifact_name);
            self.finishLocalStructuralCachedDbMutation(table_name);
        } else {
            self.beginLocalStructuralCacheUpdate(table_name);
            errdefer self.abortLocalStructuralCacheUpdate(table_name);
            try dropLocalArtifactEnrichment(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, artifact_name);
            self.finishLocalStructuralCacheUpdate(table_name);
        }
        self.notifyLocalChange(table_name, .structural);
    }

    fn createTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: tables_api.CreateTableRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.createTable(alloc, table_name, req);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        std.log.info("provisioned create table local begin table={s}", .{table_name});
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        self.beginLocalStructuralMutation(table_name);
        errdefer self.abortLocalStructuralMutation(table_name);

        const raw_indexes_json = req.indexes_json orelse tables_api.default_indexes_json;
        const schema_json = tables_api.effectiveSchemaJson(req.schema_json);
        const indexes_json = try tables_api.expandSchemaDerivedAlgebraicIndexesAlloc(alloc, table_name, raw_indexes_json, schema_json);
        defer alloc.free(indexes_json);
        for (group_ids) |group_id| {
            std.log.info("provisioned create table local group begin table={s} group_id={d}", .{ table_name, group_id });
            try deleteGroupPathIfPresent(alloc, self.replica_root_dir, group_id);
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);
            const lsm_root_generation = self.visibleRootGeneration(group_id);
            if (self.write_cache) |cache| {
                if (cache.backend_runtime == null) cache.backend_runtime = self.backend_runtime;
                cache.antfly_provider = self.antfly_provider;
                cache.inference_api_url = self.inference_api_url;
                cache.secret_store = self.secret_store;
                cache.remote_content = self.remote_content;
            }
            const seed_create_table_writer = self.seed_create_table_writers and self.write_cache != null;
            const open_mode: ManagedDbOpenMode = if (seed_create_table_writer) .default else .startup_catch_up;
            const effective_ha_mirror = haMirrorForManagedDbOpenMode(open_mode, self.ha_async_mirror);
            var opened: ?db_mod.DB = try openManagedDbWithIndexesJsonAndCacheModeWithRuntimeAndLocalAntflyAndIdentityWithOptions(
                alloc,
                path,
                indexes_json,
                if (self.write_cache) |cache| cache.lsm_cache else null,
                if (self.write_cache) |cache| cache.hbc_cache else null,
                lsm_root_generation,
                if (self.write_cache) |cache| cache.resource_manager else null,
                open_mode,
                if (self.write_cache) |cache| cache.backend_runtime else self.backend_runtime,
                self.antfly_provider,
                self.secret_store,
                self.remote_content,
                identity_namespace,
                .{
                    .inference_api_url = self.inference_api_url,
                    .drain_resolver_backfill = false,
                    .ha_write_gate = self.ha_write_gate,
                    .ha_async_effect_mirror = effective_ha_mirror,
                    .ha_async_batch_mirror = effective_ha_mirror,
                    .ha_async_metadata_mirror = effective_ha_mirror,
                },
            );
            defer if (opened) |*db| db.close();
            try applyLocalTableSchemaJson(alloc, &opened.?, schema_json);
            // Register entity resolvers declared in the index config. Indexes
            // and enrichments are provisioned through the managed-open path, but
            // resolvers are not, so do it here (idempotent: addResolver skips
            // names that already exist on reopen).
            _ = try metadata_table_provisioner.ensureResolversWithOptions(alloc, &opened.?, indexes_json, .{
                .drain_backfill = false,
            });
            if (seed_create_table_writer) {
                try self.write_cache.?.seedCreatedDbLocked(&opened, group_id, lsm_root_generation, table_name, indexes_json, schema_json);
            } else {
                try drainManagedDbBeforeClose(&opened.?);
            }
            std.log.info("provisioned create table local group ready table={s} group_id={d}", .{ table_name, group_id });
        }

        self.finishLocalStructuralMutation(table_name);
        std.log.info("provisioned create table local notify table={s}", .{table_name});
        self.notifyLocalChange(table_name, .structural);
        std.log.info("provisioned create table local done table={s}", .{table_name});
    }

    fn updateSchema(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        schema_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.updateSchema(alloc, table_name, schema_json);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;
        const indexes_json = try loadTableIndexesJson(alloc, self.catalog, table_name);
        defer if (indexes_json) |value| alloc.free(value);

        if (self.write_cache) |cache| {
            self.beginLocalStructuralCachedDbMutation(table_name);
            errdefer self.abortLocalStructuralCachedDbMutation(table_name);

            for (group_ids) |group_id| {
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
                defer alloc.free(path);
                const target_generation = self.visibleRootGeneration(group_id);

                var cached = try self.getOrOpenCachedDbForLocalMutation(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    false,
                );
                defer cached.deinit(alloc);
                try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, cached.db);
                try applyLocalTableSchemaJson(alloc, cached.db, schema_json);
                if (indexes_json) |value| {
                    _ = try metadata_table_provisioner.reconcileDbIndexes(alloc, cached.db, value);
                    try rebuildEmptyVersionedFullTextIndexesAfterSchemaUpdate(alloc, cached.db, value);
                }
                try drainManagedDbBeforeClose(cached.db);
                try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, cached.db);
            }

            lockAtomic(&self.local_db_mutex);
            errdefer self.local_db_mutex.unlock();
            try cache.replaceTableMetadataAndRetireEntriesLocked(table_name, indexes_json orelse "", schema_json);
            self.local_db_mutex.unlock();
            self.finishLocalStructuralCachedDbMutation(table_name);
            self.notifyLocalChange(table_name, .structural);
            return {};
        }

        self.beginLocalStructuralMutation(table_name);
        errdefer self.abortLocalStructuralMutation(table_name);

        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);

            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try applyLocalTableSchemaJson(alloc, &db, schema_json);
            if (indexes_json) |value| try rebuildEmptyVersionedFullTextIndexesAfterSchemaUpdate(alloc, &db, value);
            try drainManagedDbBeforeClose(&db);
            try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, &db);
        }

        self.finishLocalStructuralMutation(table_name);
        self.notifyLocalChange(table_name, .structural);
    }

    fn createIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
        index_json: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.createIndex(alloc, table_name, index_name, index_json);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginLocalStructuralIndexCacheUpdate(table_name);
        errdefer self.abortLocalStructuralIndexCacheUpdate(table_name);
        const managed_visibility_changed = try reconcileLocalTableIndexCreate(self, alloc, table_name, index_name);
        self.finishLocalStructuralCacheUpdate(table_name);
        self.notifyLocalChange(table_name, .structural);
        if (managed_visibility_changed) {
            self.publishWriteCacheRuntimeStatusesForTableBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, .data);
        }
    }

    fn dropIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.dropIndex(alloc, table_name, index_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginLocalStructuralIndexCacheUpdate(table_name);
        errdefer self.abortLocalStructuralIndexCacheUpdate(table_name);
        runTestBeforeDropIndexWorkHook();
        if (self.write_cache) |cache| {
            _ = try reconcileCachedLocalTableIndexDrop(self, alloc, cache, table_name, index_name);
        } else {
            try dropLocalTableIndex(alloc, self.catalog, self.replica_root_dir, self.backend_runtime, table_name, index_name);
        }
        self.finishLocalStructuralCacheUpdate(table_name);
        self.notifyLocalChange(table_name, .structural);
    }

    fn dropTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_ids: []const u64,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.dropTable(alloc, table_name, group_ids);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (group_ids.len == 0) return null;

        self.beginLocalStructuralMutation(table_name);
        var structural_mutation_active = true;
        var local_db_mutex_held = true;
        errdefer if (structural_mutation_active) {
            if (local_db_mutex_held) {
                self.abortLocalStructuralMutation(table_name);
            } else {
                self.abortLocalStructuralMutationUnlockedForGroups(table_name, group_ids);
            }
        };
        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        defer {
            if (read_cache_exclusive) |*exclusive| exclusive.deinit();
        }
        self.local_db_mutex.unlock();
        local_db_mutex_held = false;
        self.drainWriteCachePendingClosesForGroups(table_name, group_ids);

        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);
            self.invalidateSharedPathCaches(path);
            const trash_path = try moveDroppedGroupPathToTrash(alloc, self.replica_root_dir, table_name, group_id);
            if (trash_path) |dropped_path| {
                try self.deleteDroppedGroupPath(alloc, dropped_path);
            }
        }
        self.finishLocalStructuralMutationUnlockedForGroups(table_name, group_ids);
        structural_mutation_active = false;
        self.notifyLocalChange(table_name, .structural);
    }

    fn canCoalesceProvisionedGroupBatch(self: *ProvisionedTableWriteSource, group: GroupBatch, req: db_mod.types.BatchRequest) bool {
        if (self.write_cache == null) return false;
        if (group.transforms.items.len != 0) return false;
        if (req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.predicates.len != 0) return false;
        return switch (req.sync_level) {
            .propose, .write => true,
            .enrichments, .full_text, .full_index => false,
        };
    }

    fn writeCoalescerActive(self: *ProvisionedTableWriteSource, table_name: []const u8, group_id: u64) bool {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse return false;
        const queue = &self.write_coalesce_queues.items[queue_index];
        return queue.draining or queue.entries.items.len != 0;
    }

    fn testingWaitForWriteCoalesceQueueEntries(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        expected_entries: usize,
    ) !void {
        if (!builtin.is_test) @compileError("testingWaitForWriteCoalesceQueueEntries is test-only");
        const deadline_ns = platform_time.monotonicNs() + 5 * std.time.ns_per_s;
        while (true) {
            const count = self.testingWriteCoalesceQueueEntryCount(table_name, group_id);
            if (count >= expected_entries) return;
            if (platform_time.monotonicNs() >= deadline_ns) return error.Timeout;
            sleepNs(std.time.ns_per_ms);
        }
    }

    fn testingWriteCoalesceQueueEntryCount(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
    ) usize {
        if (!builtin.is_test) @compileError("testingWriteCoalesceQueueEntryCount is test-only");
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse return 0;
        return self.write_coalesce_queues.items[queue_index].entries.items.len;
    }

    fn coalesceCompatibleEntry(first: *const WriteCoalesceEntry, candidate: *const WriteCoalesceEntry) bool {
        return first.sync_level == candidate.sync_level and first.timestamp_ns == candidate.timestamp_ns;
    }

    fn coalescedEntryBatchRequest(entry: *const WriteCoalesceEntry) db_mod.types.BatchRequest {
        return .{
            .sync_level = entry.sync_level,
            .timestamp_ns = entry.timestamp_ns,
        };
    }

    fn enqueueProvisionedGroupBatchCoalesced(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group: GroupBatch,
        req: db_mod.types.BatchRequest,
    ) !void {
        var entry = WriteCoalesceEntry{
            .group = try cloneWriteCoalesceGroupBatch(alloc, group),
            .sync_level = req.sync_level,
            .timestamp_ns = req.timestamp_ns,
        };
        defer freeWriteCoalesceGroupBatch(alloc, &entry.group);

        const io = self.table_activity_threaded.io();
        var should_drain = false;
        self.write_coalesce_mutex.lockUncancelable(io);
        {
            errdefer self.write_coalesce_mutex.unlock(io);
            const queue = try self.writeCoalesceQueueLocked(table_name, group.group_id);
            try queue.entries.append(std.heap.page_allocator, &entry);
            if (!queue.draining) {
                queue.draining = true;
                should_drain = true;
            }
        }
        self.write_coalesce_mutex.unlock(io);

        if (should_drain) self.drainProvisionedGroupBatchCoalescer(alloc, table_name, group.group_id);

        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        while (!entry.done) {
            self.write_coalesce_ready.waitUncancelable(io, &self.write_coalesce_mutex);
        }
        if (entry.err) |err| return err;
    }

    fn drainProvisionedGroupBatchCoalescer(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
    ) void {
        const io = self.table_activity_threaded.io();
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        while (true) {
            var entries = std.ArrayListUnmanaged(*WriteCoalesceEntry).empty;
            defer entries.deinit(alloc);

            self.write_coalesce_mutex.lockUncancelable(io);
            {
                const queue_index = self.findWriteCoalesceQueueLocked(table_name, group_id) orelse {
                    self.write_coalesce_mutex.unlock(io);
                    return;
                };
                const queue = &self.write_coalesce_queues.items[queue_index];
                if (queue.entries.items.len == 0) {
                    queue.draining = false;
                    self.write_coalesce_ready.broadcast(io);
                    self.pruneWriteCoalesceQueueLocked(queue_index);
                    self.write_coalesce_mutex.unlock(io);
                    return;
                }

                const first = queue.entries.items[0];
                var take: usize = 0;
                var ops: usize = 0;
                while (take < queue.entries.items.len and take < provisioned_write_coalesce_max_waiters) : (take += 1) {
                    const candidate = queue.entries.items[take];
                    if (!coalesceCompatibleEntry(first, candidate)) break;
                    const candidate_ops = candidate.group.writes.items.len + candidate.group.deletes.items.len;
                    if (take > 0 and ops + candidate_ops > provisioned_write_coalesce_max_ops) break;
                    ops += candidate_ops;
                }
                entries.appendSlice(alloc, queue.entries.items[0..take]) catch |err| {
                    for (queue.entries.items) |entry| {
                        entry.err = err;
                        entry.done = true;
                    }
                    queue.entries.clearRetainingCapacity();
                    queue.draining = false;
                    self.write_coalesce_ready.broadcast(io);
                    self.pruneWriteCoalesceQueueLocked(queue_index);
                    self.write_coalesce_mutex.unlock(io);
                    return;
                };
                std.mem.copyForwards(*WriteCoalesceEntry, queue.entries.items[0 .. queue.entries.items.len - take], queue.entries.items[take..]);
                queue.entries.items.len -= take;
            }
            self.write_coalesce_mutex.unlock(io);

            self.applyCoalescedEntriesWithIsolation(alloc, table_name, group_id, entries.items);
        }
    }

    fn applyCoalescedEntriesWithIsolation(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        entries: []const *WriteCoalesceEntry,
    ) void {
        std.debug.assert(entries.len > 0);
        if (entries.len == 1) {
            const entry = entries[0];
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const apply_err: ?anyerror = blk: {
                self.applyProvisionedGroupBatchLocked(arena.allocator(), table_name, entry.group, coalescedEntryBatchRequest(entry)) catch |err| break :blk err;
                break :blk null;
            };
            self.finishCoalescedEntry(entry, apply_err);
            return;
        }

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();

        // A merged batch is only correct when the waiters touch disjoint
        // keys: DB batch application resolves writes before deletes
        // regardless of request order, so cross-waiter same-key merging
        // would invert enqueue order (an earlier delete beating a later
        // write), and collapsing ops per key would acknowledge a waiter
        // whose operation was never validated or applied. On any overlap,
        // fall back to applying the waiters individually in enqueue order,
        // which preserves per-key last-operation-wins and per-waiter error
        // isolation.
        const overlap = coalescedEntriesShareKeys(arena_alloc, entries) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        if (overlap) {
            self.applyCoalescedEntriesIndividually(alloc, table_name, entries);
            return;
        }

        var merged = GroupBatch{ .group_id = group_id };
        merged.writes.ensureTotalCapacity(arena_alloc, totalCoalescedWrites(entries)) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        merged.deletes.ensureTotalCapacity(arena_alloc, totalCoalescedDeletes(entries)) catch |err| {
            self.finishCoalescedEntries(entries, err);
            return;
        };
        for (entries) |entry| {
            for (entry.group.writes.items) |write| merged.writes.appendAssumeCapacity(write);
            for (entry.group.deletes.items) |key| merged.deletes.appendAssumeCapacity(key);
        }

        const merged_req = coalescedEntryBatchRequest(entries[0]);
        // Default timestamp_ns=0 intentionally remains a DB-batch timestamp:
        // coalescing preserves ordinary batch semantics and excludes CAS,
        // graph, transform, and derived-visibility writes.
        self.applyProvisionedGroupBatchLocked(arena_alloc, table_name, merged, merged_req) catch |merged_err| {
            std.log.warn("coalesced provisioned batch failed; retrying waiters individually table={s} group_id={} waiters={} err={s}", .{
                table_name,
                group_id,
                entries.len,
                @errorName(merged_err),
            });
            self.applyCoalescedEntriesIndividually(alloc, table_name, entries);
            return;
        };
        self.finishCoalescedEntries(entries, null);
    }

    fn applyCoalescedEntriesIndividually(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        entries: []const *WriteCoalesceEntry,
    ) void {
        for (entries) |entry| {
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const apply_err: ?anyerror = blk: {
                self.applyProvisionedGroupBatchLocked(arena.allocator(), table_name, entry.group, coalescedEntryBatchRequest(entry)) catch |err| break :blk err;
                break :blk null;
            };
            self.finishCoalescedEntry(entry, apply_err);
        }
    }

    // True when any key appears more than once across the coalesced waiters'
    // writes and deletes (including twice within one waiter's batch).
    fn coalescedEntriesShareKeys(
        arena_alloc: std.mem.Allocator,
        entries: []const *WriteCoalesceEntry,
    ) !bool {
        var seen = std.StringHashMapUnmanaged(void).empty;
        for (entries) |entry| {
            for (entry.group.writes.items) |write| {
                const gop = try seen.getOrPut(arena_alloc, write.key);
                if (gop.found_existing) return true;
            }
            for (entry.group.deletes.items) |key| {
                const gop = try seen.getOrPut(arena_alloc, key);
                if (gop.found_existing) return true;
            }
        }
        return false;
    }

    fn totalCoalescedWrites(entries: []const *WriteCoalesceEntry) usize {
        var total: usize = 0;
        for (entries) |entry| total += entry.group.writes.items.len;
        return total;
    }

    fn totalCoalescedDeletes(entries: []const *WriteCoalesceEntry) usize {
        var total: usize = 0;
        for (entries) |entry| total += entry.group.deletes.items.len;
        return total;
    }

    fn finishCoalescedEntries(self: *ProvisionedTableWriteSource, entries: []const *WriteCoalesceEntry, err: ?anyerror) void {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        for (entries) |entry| {
            entry.err = err;
            entry.done = true;
        }
        self.write_coalesce_ready.broadcast(io);
    }

    fn finishCoalescedEntry(self: *ProvisionedTableWriteSource, entry: *WriteCoalesceEntry, err: ?anyerror) void {
        const io = self.table_activity_threaded.io();
        self.write_coalesce_mutex.lockUncancelable(io);
        defer self.write_coalesce_mutex.unlock(io);
        entry.err = err;
        entry.done = true;
        self.write_coalesce_ready.broadcast(io);
    }

    fn applyProvisionedGroupBatchLocked(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group: GroupBatch,
        req: db_mod.types.BatchRequest,
    ) !void {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group.group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group.group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group.group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);
            try applyGroupBatchWithSchemaJson(alloc, cached.db, cached.schema_json, group, req);
            cache.publishCachedLeaseGeneration(&cached, target_generation);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group.group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group.group_id, &db);
            try applyGroupBatch(alloc, self.catalog, &db, table_name, group, req);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group.group_id, &db);
        }
    }

    fn batch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.raft_batcher == null) {
            if (self.localWriteOwnerSource()) |owner| return try owner.batch(alloc, table_name, req);
        }
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        errdefer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
            self.invalidateWriteCache(table_name);
        }
        var grouped = std.ArrayListUnmanaged(GroupBatch).empty;
        defer {
            for (grouped.items) |*group| group.deinit(alloc);
            grouped.deinit(alloc);
        }

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return null;
        const ranges = try metadata_admin.listTableRanges(alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);
        if (ranges.len == 0) return null;

        for (req.writes) |write| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, write.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.writes.append(alloc, write);
        }
        for (req.deletes) |key| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.deletes.append(alloc, key);
        }
        for (req.transforms) |transform| {
            const group_id = table_catalog.resolveGroupForKeyFromRanges(ranges, transform.key) orelse return null;
            const group = try ensureGroupBatch(alloc, &grouped, group_id);
            try group.transforms.append(alloc, transform);
        }

        if (self.raft_batcher) |batcher| {
            for (grouped.items) |group| {
                try batcher.batchGroup(alloc, group.group_id, table_name, .{
                    .writes = group.writes.items,
                    .deletes = group.deletes.items,
                    .transforms = group.transforms.items,
                    .sync_level = req.sync_level,
                });
            }
            return {};
        }

        for (grouped.items) |group| {
            if (self.canCoalesceProvisionedGroupBatch(group, req)) {
                if (self.writeCoalescerActive(table_name, group.group_id)) {
                    try self.enqueueProvisionedGroupBatchCoalesced(alloc, table_name, group, req);
                } else if (self.tryBeginGroupOperation(table_name, group.group_id)) {
                    defer self.endGroupOperation(table_name, group.group_id);
                    try self.applyProvisionedGroupBatchLocked(alloc, table_name, group, req);
                } else {
                    try self.enqueueProvisionedGroupBatchCoalesced(alloc, table_name, group, req);
                }
            } else {
                self.beginGroupOperation(table_name, group.group_id);
                defer self.endGroupOperation(table_name, group.group_id);
                try self.applyProvisionedGroupBatchLocked(alloc, table_name, group, req);
            }
        }
        lockAtomic(&self.local_db_mutex);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
        self.notifyLocalChange(table_name, .data);
    }

    fn beginRestoreLifecycle(ptr: *anyopaque, table_name: []const u8) !void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            _ = try owner.beginRestoreLifecycle(table_name);
        }
        self.beginRestoreLifecycleActivity(table_name);
    }

    fn finishRestoreLifecycle(ptr: *anyopaque, table_name: []const u8) void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| {
            owner.finishRestoreLifecycle(table_name);
        }
        self.endRestoreLifecycleActivity(table_name);
    }

    fn backupTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableBackupPlan,
    ) !?[]backups_api.ShardSnapshot {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.backupTable(alloc, table_name, plan);

        const group_id = (try table_catalog.resolveSingleRangeGroup(alloc, self.catalog, table_name)) orelse return null;
        self.beginGroupOperation(table_name, group_id);
        defer {
            self.endGroupOperation(table_name, group_id);
        }

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (plan.format == .portable) {
            var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            if (self.write_cache) |cache| {
                const target_generation = self.visibleRootGeneration(group_id);
                var cached = try self.getOrOpenCachedDbForLocalMutation(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    true,
                );
                defer cached.deinit(alloc);
                return try exportPortableBackupShard(alloc, cached.db, plan.backup_root, plan.backup_id, group_id, plan.io);
            }

            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            return try exportPortableBackupShard(alloc, &db, plan.backup_root, plan.backup_id, group_id, plan.io);
        }

        if (self.write_cache) |cache| {
            var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
            defer {
                if (read_cache_exclusive) |*exclusive| exclusive.deinit();
            }
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);

            var native_snapshot = try prepareNativeBackupShardSnapshot(alloc, cached.db, path, group_id, plan);
            defer native_snapshot.deinit(alloc);
            if (read_cache_exclusive) |*exclusive| {
                exclusive.deinit();
                read_cache_exclusive = null;
            }
            return try copyPreparedNativeBackupShardSnapshot(alloc, &native_snapshot);
        }

        var read_cache_exclusive = try self.beginReadCacheExclusive(table_name);
        defer {
            if (read_cache_exclusive) |*exclusive| exclusive.deinit();
        }
        var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
        defer db.close();
        var native_snapshot = try prepareNativeBackupShardSnapshot(alloc, &db, path, group_id, plan);
        defer native_snapshot.deinit(alloc);
        if (read_cache_exclusive) |*exclusive| {
            exclusive.deinit();
            read_cache_exclusive = null;
        }
        return try copyPreparedNativeBackupShardSnapshot(alloc, &native_snapshot);
    }

    const NativeBackupShardSnapshot = struct {
        snapshot_root: []const u8,
        dest_root: []const u8,
        shard: backups_api.ShardSnapshot,
        owns_shard: bool = true,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(@constCast(self.snapshot_root));
            alloc.free(@constCast(self.dest_root));
            if (self.owns_shard) self.shard.deinit(alloc);
            self.* = undefined;
        }

        fn toShardsAlloc(self: *@This(), alloc: std.mem.Allocator) ![]backups_api.ShardSnapshot {
            const shards = try alloc.alloc(backups_api.ShardSnapshot, 1);
            shards[0] = self.shard;
            self.owns_shard = false;
            return shards;
        }
    };

    fn prepareNativeBackupShardSnapshot(
        alloc: std.mem.Allocator,
        db: *db_mod.DB,
        db_path: []const u8,
        group_id: u64,
        plan: backups_api.TableBackupPlan,
    ) !NativeBackupShardSnapshot {
        std.debug.assert(plan.format == .native);

        const snapshot_token = try std.fmt.allocPrint(alloc, "{s}-g{d}", .{ plan.backup_id, group_id });
        defer alloc.free(snapshot_token);
        _ = try db.snapshot(snapshot_token);

        const snapshot_root = try std.fmt.allocPrint(alloc, "{s}.snapshots/{s}", .{ db_path, snapshot_token });
        errdefer alloc.free(snapshot_root);
        const dest_root = try backups_api.shardSnapshotPath(alloc, plan.backup_root, plan.backup_id, group_id);
        errdefer alloc.free(dest_root);
        const rel_path = try backups_api.shardSnapshotRelPath(alloc, plan.backup_id, group_id);
        errdefer alloc.free(rel_path);

        const byte_range = db.getRange();
        const start_key = try alloc.dupe(u8, byte_range.start);
        errdefer alloc.free(start_key);
        const end_key = if (byte_range.end.len > 0) try alloc.dupe(u8, byte_range.end) else null;
        errdefer if (end_key) |value| alloc.free(value);

        return .{
            .snapshot_root = snapshot_root,
            .dest_root = dest_root,
            .shard = .{
                .group_id = group_id,
                .start_key = start_key,
                .end_key = end_key,
                .snapshot_path = rel_path,
            },
        };
    }

    fn copyPreparedNativeBackupShardSnapshot(
        alloc: std.mem.Allocator,
        native_snapshot: *NativeBackupShardSnapshot,
    ) ![]backups_api.ShardSnapshot {
        runTestBeforeNativeBackupCopyHook();
        try backups_api.copyDirectoryRecursive(alloc, native_snapshot.snapshot_root, native_snapshot.dest_root);
        return try native_snapshot.toShardsAlloc(alloc);
    }

    fn restoreTable(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        plan: backups_api.TableRestorePlan,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.restoreTableReserved(alloc, table_name, plan);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        try backups_api.validateRestorableManifestLayout(plan.manifest);
        if (plan.reconcile_only and plan.replace_existing) return error.InvalidBackupRequest;

        const local_location = try std.fmt.allocPrint(alloc, "file://{s}", .{plan.backup_root});
        defer alloc.free(local_location);

        const source_shard = plan.manifest.shards[0];
        const group_id = if (plan.replace_existing)
            (try table_catalog.resolveSingleRangeGroup(alloc, self.catalog, table_name)) orelse return null
        else
            source_shard.group_id;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const restore_source: backup_restore.RestoreSource = .{
            .backup_id = plan.manifest.backup_id,
            .location = local_location,
            .identity_location = plan.source_location,
            .snapshot_path = source_shard.snapshot_path,
            .manifest = plan.manifest,
        };

        var all_groups_already_admitted = true;
        var admitted_identity_mismatch = false;
        if (!try db_mod.generation_lifecycle.hasPublishedGenerationRead(path)) {
            all_groups_already_admitted = false;
        } else {
            const validation = if (plan.reconcile_only)
                backup_restore.validateCommittedRestoreIdentity(alloc, path, group_id, restore_source)
            else
                backup_restore.validateImportedRestoreIdentity(alloc, path, group_id, restore_source);
            validation catch |err| switch (err) {
                error.RestoreIdentityMismatch => {
                    admitted_identity_mismatch = true;
                    all_groups_already_admitted = false;
                },
                else => return err,
            };
        }
        if (all_groups_already_admitted and plan.publication_hook == null) return;
        if (plan.reconcile_only and admitted_identity_mismatch) return error.RestoreIdentityMismatch;

        var restore_io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
        defer restore_io_impl.deinit();
        const identity_namespace = try loadTableIdentityNamespaceForGroup(alloc, self.catalog, table_name, group_id);

        const ready_deadline_ns = platform_time.monotonicNs() + 5 * std.time.ns_per_s;
        while (true) {
            if (std.Io.Dir.cwd().statFile(restore_io_impl.io(), path, .{})) |_| break else |_| {}
            if (platform_time.monotonicNs() >= ready_deadline_ns) break;
            sleepNs(50 * std.time.ns_per_ms);
        }
        runTestBeforeRestoreWorkHook();

        var preparation: ?db_mod.generation_lifecycle.PreparationTransition = null;
        defer if (preparation) |*value| value.deinit();
        var prepared_generation: ?db_mod.generation_lifecycle.StagedGeneration = null;
        defer if (prepared_generation) |*generation| generation.deinit();

        if (!plan.reconcile_only) {
            preparation = try db_mod.generation_lifecycle.beginProcessPreparationWithRuntime(path, self.backend_runtime);
            prepared_generation = backup_restore.prepareRestoreSnapshotToPathWithPreparation(&preparation.?, alloc, path, group_id, restore_source, .{
                .expected_table_name = table_name,
                .expected_identity_namespace = identity_namespace,
            }) catch |err| {
                switch (err) {
                    error.IdentityNamespaceMismatch => std.log.warn("provisioned restoreTable failed table={s} group_id={d} path={s} snapshot_path={s} err={}", .{
                        table_name,
                        group_id,
                        path,
                        source_shard.snapshot_path,
                        err,
                    }),
                    else => std.log.err("provisioned restoreTable failed table={s} group_id={d} path={s} backup_root={s} snapshot_path={s} err={}", .{
                        table_name,
                        group_id,
                        path,
                        plan.backup_root,
                        source_shard.snapshot_path,
                        err,
                    }),
                }
                return err;
            };
            // Import, derived rebuild, and validation run against the isolated
            // sibling while the current generation remains admitted.
            if (prepared_generation) |*generation| try self.repairRestoredTableRuntimeStateBlocking(
                alloc,
                generation.path(),
                group_id,
                table_name,
                plan.manifest.indexes_json,
                plan.manifest.schema_json,
                generation,
            );
            if (prepared_generation) |*generation| try generation.seal();
            if (prepared_generation == null) {
                preparation.?.deinit();
                preparation = null;
            }
        }

        var transition = try self.beginLocalTableGenerationTransitionFromPreparation(table_name);
        errdefer transition.abort();
        defer transition.deinit();
        self.invalidateSharedPathCaches(path);
        var publication_outcome: db_mod.generation_lifecycle.PublicationOutcome = .durable;
        var definition_published = false;
        errdefer if (definition_published) {
            if (plan.publication_hook) |hook| hook.rollback() catch |rollback_err| {
                std.log.err("restore metadata rollback failed table={s} err={s}", .{ table_name, @errorName(rollback_err) });
            };
        };

        if (plan.reconcile_only) {
            var shard_transition = try transition.beginShardStorageTransition(path);
            defer shard_transition.deinit();
            try backup_restore.reconcileCommittedRestoreWithExclusiveTransition(&shard_transition, alloc, path, group_id, restore_source);
        } else if (prepared_generation) |*generation| {
            var shard_transition = try preparation.?.promote();
            defer shard_transition.deinit();
            if (plan.publication_hook) |hook| {
                try hook.publish();
                definition_published = true;
            }
            publication_outcome = try backup_restore.publishPreparedRestore(alloc, path, generation);
            definition_published = false;
            if (publication_outcome == .durability_uncertain) {
                std.log.err("restore generation published with uncertain durability table={s} group_id={d} path={s}", .{ table_name, group_id, path });
            }
        } else {
            // An idempotent retry may only owe runtime repair on the already
            // published generation. Keep that maintenance under exclusivity.
            var shard_transition = try transition.beginShardStorageTransition(path);
            defer shard_transition.deinit();
            try self.repairRestoredTableRuntimeStateBlocking(
                alloc,
                path,
                group_id,
                table_name,
                plan.manifest.indexes_json,
                plan.manifest.schema_json,
                null,
            );
            if (plan.publication_hook) |hook| try hook.publish();
        }

        self.invalidateSharedPathCaches(path);
        transition.finishMutation();
        self.publishRestoreRepairComplete(table_name);
        self.notifyLocalChange(table_name, .structural);
        self.notifyLocalChange(table_name, .data);
        if (publication_outcome == .durability_uncertain) return error.GenerationDurabilityUncertain;
    }

    fn commitTransaction(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        const txn_id = nextTxnId();
        return try commitTransactionWithId(ptr, alloc, txn_id, nextTxnTimestamp(), tables, sync_level);
    }

    fn commitTransactionWithId(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        if (try self.commitSingleGroupTransactionViaRaftBatcher(alloc, tables, sync_level)) |outcome| return outcome;
        var worker_impl = distributed_txn.LocalTableWriteParticipantWorker.init(self.source());
        const commit_version = begin_timestamp + 1;
        return try distributed_txn.executeMultiTableCommit(
            alloc,
            self.catalog,
            worker_impl.worker(),
            txn_id,
            begin_timestamp,
            commit_version,
            tables,
            if (comptime build_options.with_tla) tracing.stderrAntflyTraceWriter() else null,
        );
    }

    fn commitSingleGroupTransactionViaRaftBatcher(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        tables: []const distributed_txn.TableCommitRequest,
        sync_level: db_mod.types.SyncLevel,
    ) !?distributed_txn.CommitOutcome {
        const batcher = self.raft_batcher orelse return null;
        if (tables.len == 0) return .{ .committed = .{ .participant_count = 0 } };
        if (tables.len != 1) return null;
        const table_req = tables[0];
        if (table_req.predicates.len != 0) return null;

        var snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_req.table_name) orelse return null;
        const ranges = try metadata_admin.listTableRanges(alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(alloc, ranges);
        if (ranges.len == 0) return null;

        var group_id_opt: ?u64 = null;
        const resolveOpGroup = struct {
            fn run(current: *?u64, range_refs: []const *const metadata_table_manager.RangeRecord, key: []const u8) !void {
                const group_id = table_catalog.resolveGroupForKeyFromRanges(range_refs, key) orelse return error.NotFound;
                if (current.*) |existing| {
                    if (existing != group_id) return error.MultipleGroups;
                } else {
                    current.* = group_id;
                }
            }
        }.run;

        for (table_req.writes) |write| resolveOpGroup(&group_id_opt, ranges, write.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.deletes) |key| resolveOpGroup(&group_id_opt, ranges, key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        for (table_req.transforms) |transform| resolveOpGroup(&group_id_opt, ranges, transform.key) catch |err| switch (err) {
            error.MultipleGroups => return null,
            else => return err,
        };
        const group_id = group_id_opt orelse return .{ .committed = .{ .participant_count = 0 } };

        var batch_writes: []db_mod.types.BatchWrite = &.{};
        if (table_req.writes.len != 0) {
            batch_writes = try alloc.alloc(db_mod.types.BatchWrite, table_req.writes.len);
            defer alloc.free(batch_writes);
            for (table_req.writes, 0..) |write, i| {
                batch_writes[i] = .{ .key = write.key, .value = write.value };
            }
        }

        try batcher.batchGroup(alloc, group_id, table_req.table_name, .{
            .writes = batch_writes,
            .deletes = table_req.deletes,
            .transforms = table_req.transforms,
            .sync_level = sync_level,
        });
        return .{ .committed = .{ .participant_count = 1 } };
    }

    fn batchGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.raft_batcher) |batcher| {
            try enforceHAWriteGateOptional(self.ha_write_gate);
            try batcher.batchGroupLocal(alloc, group_id, table_name, req);
            return {};
        }
        if (self.localWriteOwnerSource()) |owner| return try owner.batchGroupLocal(alloc, group_id, table_name, req);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        return try self.applyReplicatedBatchGroupLocal(alloc, group_id, table_name, req);
    }

    pub fn applyReplicatedBatchGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) !?void {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const apply_req = req;
        const split_identity_namespace = try validateSplitReplicationForApply(apply_req, group_id);
        if (apply_req.split_replication) |replication| {
            try validateSplitReplicationIdentityAgainstCatalog(alloc, self.catalog, table_name, replication);
        }
        self.beginGroupOperation(table_name, group_id);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        defer {
            self.endGroupOperation(table_name, group_id);
        }
        errdefer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
            self.invalidateWriteCache(table_name);
        }
        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = if (split_identity_namespace) |namespace|
                (try self.leaseCachedTransitionGroupWriter(alloc, group_id, table_name, namespace)) orelse
                    return error.TableNotFound
            else
                try self.getOrOpenCachedDbForLocalMutation(
                    alloc,
                    cache,
                    path,
                    group_id,
                    target_generation,
                    table_name,
                    true,
                );
            defer cached.deinit(alloc);
            try validateTableBatchAgainstSchemaJson(alloc, cached.db, cached.schema_json, apply_req.writes, apply_req.deletes, apply_req.transforms);
            runTestBeforeBatchExecutionHook();
            if (apply_req.split_checkpoint) |checkpoint| {
                if (checkpoint.destination_group_id != group_id and checkpoint.source_group_id != group_id) {
                    return error.InvalidBatchRequest;
                }
                if (checkpoint.kind == .destination) {
                    if (checkpoint.destination_group_id != group_id) return error.InvalidBatchRequest;
                    _ = try cached.db.replaceSplitBootstrap(
                        alloc,
                        .{ .start = checkpoint.range_start, .end = checkpoint.range_end },
                        apply_req.writes,
                        checkpoint.delta_sequence,
                        .{
                            .transition_id = checkpoint.transition_id,
                            .attempt_epoch = checkpoint.attempt_epoch,
                            .source_group_id = checkpoint.source_group_id,
                            .destination_group_id = checkpoint.destination_group_id,
                            .bootstrap_complete = true,
                        },
                    );
                } else if (checkpoint.source_group_id != group_id) return error.InvalidBatchRequest;
            } else if (apply_req.split_replication) |replication| {
                try validateSplitReplicationMarker(alloc, cached.db, replication);
            }
            if (apply_req.split_checkpoint == null or apply_req.split_checkpoint.?.kind != .destination) {
                try cached.db.batchReplicatedApply(apply_req);
            }
            cache.publishCachedLeaseGeneration(&cached, target_generation);
            {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                self.markWriteCacheDirty(table_name);
            }
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, .data);
        } else {
            var db = try openManagedDbForReplicatedApply(
                alloc,
                path,
                self.catalog,
                table_name,
                group_id,
                self.backend_runtime,
                self.ha_write_gate,
                self.ha_async_mirror,
                split_identity_namespace,
            );
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try validateTableBatchAgainstCatalogSchema(alloc, self.catalog, &db, table_name, apply_req.writes, apply_req.deletes, apply_req.transforms);
            runTestBeforeBatchExecutionHook();
            if (apply_req.split_checkpoint) |checkpoint| {
                if (checkpoint.destination_group_id != group_id and checkpoint.source_group_id != group_id) {
                    return error.InvalidBatchRequest;
                }
                if (checkpoint.kind == .destination) {
                    if (checkpoint.destination_group_id != group_id) return error.InvalidBatchRequest;
                    _ = try db.replaceSplitBootstrap(
                        alloc,
                        .{ .start = checkpoint.range_start, .end = checkpoint.range_end },
                        apply_req.writes,
                        checkpoint.delta_sequence,
                        .{
                            .transition_id = checkpoint.transition_id,
                            .attempt_epoch = checkpoint.attempt_epoch,
                            .source_group_id = checkpoint.source_group_id,
                            .destination_group_id = checkpoint.destination_group_id,
                            .bootstrap_complete = true,
                        },
                    );
                } else if (checkpoint.source_group_id != group_id) return error.InvalidBatchRequest;
            } else if (apply_req.split_replication) |replication| {
                try validateSplitReplicationMarker(alloc, &db, replication);
            }
            if (apply_req.split_checkpoint == null or apply_req.split_checkpoint.?.kind != .destination) {
                try db.batchReplicatedApply(apply_req);
            }
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, .data);
        }
    }

    pub fn installRaftSnapshotGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        encoded: []const u8,
    ) !void {
        var state = try shard_state_store.decodeGroupStateSnapshotAlloc(alloc, encoded);
        defer state.deinit(alloc);
        try shard_state_store.validateGroupStateSnapshot(alloc, group_id, state);

        var catalog_snapshot = try self.catalog.adminSnapshot();
        defer self.catalog.freeAdminSnapshot(&catalog_snapshot);
        const range = metadata_mod.findAdminRange(&catalog_snapshot, group_id) orelse return error.UnknownGroup;
        const table = metadata_mod.findAdminTable(&catalog_snapshot, range.table_id) orelse return error.TableNotFound;
        const table_name = table.name;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const writes = try alloc.alloc(db_mod.types.BatchWrite, state.entries.len);
        defer alloc.free(writes);
        for (state.entries, 0..) |entry, i| writes[i] = .{ .key = entry.key, .value = entry.value };

        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        errdefer {
            lockAtomic(&self.local_db_mutex);
            defer self.local_db_mutex.unlock();
            self.invalidateReadCache(table_name);
            self.invalidateWriteCache(table_name);
        }

        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);
            try validateTableBatchAgainstSchemaJson(alloc, cached.db, cached.schema_json, writes, &.{}, &.{});
            try cached.db.replaceRaftDocumentSnapshot(alloc, state.byte_range, writes);
            cache.publishCachedLeaseGeneration(&cached, target_generation);
        } else {
            var db = try openManagedDbForReplicatedApply(
                alloc,
                path,
                self.catalog,
                table_name,
                group_id,
                self.backend_runtime,
                self.ha_write_gate,
                self.ha_async_mirror,
                null,
            );
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try validateTableBatchAgainstCatalogSchema(alloc, self.catalog, &db, table_name, writes, &.{}, &.{});
            try db.replaceRaftDocumentSnapshot(alloc, state.byte_range, writes);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
        lockAtomic(&self.local_db_mutex);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
        self.notifyLocalChange(table_name, .data);
    }

    pub fn applyHAReplicationRecordGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        record: db_mod.HAReplicationRecordView,
    ) !void {
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        if (self.write_cache) |cache| {
            const target_generation = self.visibleRootGeneration(group_id);
            var cached = try self.getOrOpenCachedDbForLocalMutation(
                alloc,
                cache,
                path,
                group_id,
                target_generation,
                table_name,
                true,
            );
            defer cached.deinit(alloc);
            try cached.db.applyHAReplicationRecord(record);
            cache.publishCachedLeaseGeneration(&cached, target_generation);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, changeKindForHARecord(record));
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.applyHAReplicationRecord(record);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            self.notifyLocalChange(table_name, changeKindForHARecord(record));
        }
    }

    pub fn syncReplicatedBatchGroupLocal(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        sync_level: db_mod.types.SyncLevel,
    ) !void {
        switch (sync_level) {
            .propose, .write => return,
            .enrichments, .full_text, .full_index => {},
        }

        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);

        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(
                alloc,
                cache,
                path,
                group_id,
                table_name,
                .default_async,
                null,
                null,
            );
            defer cached.deinit(alloc);
            try cached.db.waitForCurrentSyncLevel(sync_level);
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.waitForCurrentSyncLevel(sync_level);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
        self.notifyLocalChange(table_name, .data);
    }

    fn finishTransientManagedDbWriteBeforeClose(
        self: *ProvisionedTableWriteSource,
        table_name: []const u8,
        group_id: u64,
        db: *db_mod.DB,
    ) void {
        if (self.runtime_status_cache != null) {
            drainManagedDbBeforeClose(db) catch |err| {
                if (!isTransientReplayVisibilityError(err)) {
                    std.log.warn("transient managed writer drain before status publish failed table={s} group_id={} err={s}", .{
                        table_name,
                        group_id,
                        @errorName(err),
                    });
                }
            };
            _ = self.publishManagedRuntimeStatusBestEffort(table_name, group_id, db);
        }
    }

    fn txnBeginGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        begin_timestamp: u64,
        topology_epoch: u64,
        participants: []const []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        try table_catalog.validateTopologyEpoch(alloc, self.catalog, table_name, topology_epoch);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try recoverProvisionedTransactionsOnce(self, alloc, cached.db);
            _ = try cached.db.beginTransactionWithIdAndParticipants(txn_id, begin_timestamp, participants);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try recoverProvisionedTransactionsOnce(self, alloc, &db);
            _ = try db.beginTransactionWithIdAndParticipants(txn_id, begin_timestamp, participants);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
    }

    fn txnPrepareGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        topology_epoch: u64,
        req: db_mod.types.TransactionIntentRequest,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        try table_catalog.validateTopologyEpoch(alloc, self.catalog, table_name, topology_epoch);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try recoverProvisionedTransactionsOnce(self, alloc, cached.db);
            try validateTransactionAgainstCatalogSchema(alloc, self.catalog, cached.db, table_name, req.writes, req.deletes, req.transforms);
            try cached.db.writeTransaction(txn_id, req);
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try recoverProvisionedTransactionsOnce(self, alloc, &db);
            try validateTransactionAgainstCatalogSchema(alloc, self.catalog, &db, table_name, req.writes, req.deletes, req.transforms);
            try db.writeTransaction(txn_id, req);
            self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
    }

    fn txnResolveGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
        status: db_mod.types.TxnStatus,
        commit_version: u64,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        if (status == .committed) {
            lockAtomic(&self.local_db_mutex);
            self.invalidateReadCache(table_name);
            self.markWriteCacheDirty(table_name);
            self.local_db_mutex.unlock();
            errdefer {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                self.invalidateReadCache(table_name);
                self.invalidateWriteCache(table_name);
            }
        }
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try cached.db.resolveTransactionIntents(txn_id, status, commit_version);
            if (status == .committed) try drainManagedDbBeforeClose(cached.db);
            const participant = try std.fmt.allocPrint(alloc, "group:{d}", .{group_id});
            defer alloc.free(participant);
            try cached.db.markTransactionParticipantResolved(txn_id, participant);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try db.resolveTransactionIntents(txn_id, status, commit_version);
            if (status == .committed) try drainManagedDbBeforeClose(&db);
            const participant = try std.fmt.allocPrint(alloc, "group:{d}", .{group_id});
            defer alloc.free(participant);
            try db.markTransactionParticipantResolved(txn_id, participant);
            if (status == .committed) self.finishTransientManagedDbWriteBeforeClose(table_name, group_id, &db);
        }
        if (status == .committed) {
            lockAtomic(&self.local_db_mutex);
            self.markWriteCacheDirty(table_name);
            self.invalidateReadCache(table_name);
            self.local_db_mutex.unlock();
            self.publishDirtyWriteCacheRuntimeStatusesBestEffort(alloc, table_name);
            self.notifyLocalChange(table_name, .data);
        }
    }

    fn txnStatusGroupLocal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        txn_id: db_mod.types.TxnId,
    ) !?db_mod.types.TxnStatus {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        self.beginGroupOperation(table_name, group_id);
        defer self.endGroupOperation(table_name, group_id);
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        if (self.write_cache) |cache| {
            var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default_async, null, null);
            defer cached.deinit(alloc);
            try recoverProvisionedTransactionsOnce(self, alloc, cached.db);
            return try cached.db.getTransactionStatus(txn_id);
        } else {
            var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
            defer db.close();
            try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
            try recoverProvisionedTransactionsOnce(self, alloc, &db);
            return try db.getTransactionStatus(txn_id);
        }
    }

    fn localRuntimeStatuses(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.localRuntimeStatuses(alloc, table_name);
        // Status must not observe a structural generation transition, but it
        // is safe to serve immutable snapshots during ordinary group work.
        // The narrower admission avoids deadlocking status callers that run
        // inside a group operation while still fencing restore/drop/publish.
        self.beginStatusRequest(table_name);
        defer self.endReadRequest(table_name);
        return try self.snapshotRuntimeStatusesBestEffort(alloc, table_name);
    }

    fn collectRuntimeStatusLeasesFromWriteCacheLocked(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        out: *std.ArrayListUnmanaged(ProvisionedTableWriteCache.CachedDb),
    ) !bool {
        const cache = self.write_cache orelse return false;
        out.clearRetainingCapacity();

        if (self.isWriteCacheDirtyForTable(table_name)) {
            _ = try cache.finishExpiredAutoBulkIngestLocked(platform_time.monotonicNs());
        }

        var i: usize = 0;
        while (i < cache.entries.items.len) {
            const entry = cache.entries.items[i];
            if (!std.mem.eql(u8, entry.table_name, table_name)) {
                i += 1;
                continue;
            }
            if (entry.lsm_root_generation == self.visibleRootGeneration(entry.group_id)) {
                i += 1;
                continue;
            }
            if (cache.adoptSeededEntryGenerationLocked(entry, self.visibleRootGeneration(entry.group_id))) {
                i += 1;
                continue;
            }
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) {
                i += 1;
                continue;
            }
            if (try cache.retireInactiveEntryAtIndexForCloseLocked(i)) continue;
            i += 1;
        }

        var matching_entries: usize = 0;
        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) continue;
            matching_entries += 1;
        }
        try out.ensureTotalCapacity(alloc, matching_entries);

        for (cache.entries.items) |entry| {
            if (!std.mem.eql(u8, entry.table_name, table_name)) continue;
            if (entry.lsm_root_generation != self.visibleRootGeneration(entry.group_id)) continue;
            if (entry.bulk_ingest_session_open or entry.auto_bulk_ingest_session_open) continue;
            lockAtomic(&cache.entry_lifecycle_mutex);
            entry.active_leases += 1;
            cache.entry_lifecycle_mutex.unlock();
            out.appendAssumeCapacity(.{
                .cache = cache,
                .entry = entry,
                .db = &entry.db,
                .schema_json = entry.schema_json,
            });
        }
        return out.items.len != 0;
    }

    fn runtimeStatusesFromCachedDbLeasesBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        leases: []const ProvisionedTableWriteCache.CachedDb,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const snapshot_cache = self.runtime_status_cache orelse return null;
        if (self.isWriteCacheDirtyForTable(table_name)) {
            if (self.write_cache) |cache| {
                lockAtomic(&self.local_db_mutex);
                defer self.local_db_mutex.unlock();
                _ = try cache.finishExpiredAutoBulkIngestLocked(platform_time.monotonicNs());
            }
        }
        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        errdefer {
            for (items.items) |*item| item.deinit(alloc);
            items.deinit(alloc);
        }

        try items.ensureTotalCapacity(alloc, leases.len);
        for (leases) |lease| {
            const group_id = lease.entry.?.group_id;
            try publishRuntimeStatusSnapshotConsistent(self, alloc, table_name, group_id, lease.db);
            var owned_status = (try snapshot_cache.snapshotGroupStatus(alloc, table_name, group_id)) orelse continue;
            errdefer owned_status.deinit(alloc);
            try self.overlayReadCacheIndexVisibilityBestEffort(alloc, table_name, group_id, &owned_status);
            items.appendAssumeCapacity(owned_status);
        }
        if (items.items.len == 0) {
            items.deinit(alloc);
            return try snapshot_cache.snapshot(alloc, table_name);
        }
        return .{ .items = try items.toOwnedSlice(alloc) };
    }

    fn overlayReadCacheHbcStatsBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        const read_cache = self.read_cache orelse return;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        var read_lease = read_cache.getOrOpen(
            path,
            self.catalog,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
        ) catch return;
        defer read_lease.release();

        overlayDenseHbcCacheStatsFromDb(&status.stats, read_lease.db);
        if (self.runtime_status_cache) |snapshot_cache| {
            try snapshot_cache.upsertGroupStatus(table_name, status.*);
        }
    }

    fn overlayReadCacheIndexVisibilityBestEffort(
        self: *ProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        group_id: u64,
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        if (self.isWriteCacheDirtyForTable(table_name)) return;
        if (self.hasActiveBulkIngestSessionForTableBestEffort(table_name)) return;

        const read_cache = self.read_cache orelse return;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);

        var read_lease = read_cache.getOrOpen(
            path,
            self.catalog,
            group_id,
            self.visibleRootGeneration(group_id),
            table_name,
        ) catch return;
        defer read_lease.release();

        const visible_stats = try read_lease.db.stats(alloc);
        defer db_mod.types.freeDBStats(alloc, visible_stats);

        for (status.stats.indexes) |*item| {
            const visible = for (visible_stats.indexes) |candidate| {
                if (std.mem.eql(u8, candidate.name, item.name)) break candidate;
            } else continue;

            item.doc_count = visible.doc_count;
            item.term_count = visible.term_count;
            item.edge_count = visible.edge_count;
            item.node_count = visible.node_count;
            item.hbc_cache = visible.hbc_cache;
        }

        if (self.runtime_status_cache) |snapshot_cache| {
            try snapshot_cache.upsertGroupStatus(table_name, status.*);
        }
    }

    fn corruptEmbeddingArtifact(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.corruptEmbeddingArtifact(alloc, table_name, doc_key, index_name);
        try enforceHAWriteGateOptional(self.ha_write_gate);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.markWriteCacheDirty(table_name);
        self.local_db_mutex.unlock();
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        for (group_ids) |group_id| {
            self.beginGroupOperation(table_name, group_id);
            {
                defer self.endGroupOperation(table_name, group_id);
                const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
                defer alloc.free(path);

                if (self.write_cache) |cache| {
                    var cached = try self.getOrOpenCachedDbMode(alloc, cache, path, group_id, table_name, .default, null, null);
                    defer cached.deinit(alloc);
                    if (try corruptEmbeddingArtifactInDb(alloc, cached.db, doc_key, index_name)) {
                        lockAtomic(&self.local_db_mutex);
                        self.invalidateReadCache(table_name);
                        self.markWriteCacheDirty(table_name);
                        self.local_db_mutex.unlock();
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                } else {
                    var db = try openManagedDbForTableGroupWithRuntimeAndHAWriteGate(alloc, path, self.catalog, table_name, group_id, self.backend_runtime, self.ha_write_gate, self.ha_async_mirror);
                    defer db.close();
                    try validateProvisionedDbIdentityNamespace(alloc, self.catalog, table_name, group_id, &db);
                    if (try corruptEmbeddingArtifactInDb(alloc, &db, doc_key, index_name)) {
                        lockAtomic(&self.local_db_mutex);
                        self.invalidateReadCache(table_name);
                        self.markWriteCacheDirty(table_name);
                        self.local_db_mutex.unlock();
                        self.notifyLocalChange(table_name, .data);
                        return;
                    }
                }
            }
        }

        return error.NotFound;
    }

    fn reprocessDocumentArtifact(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !?bool {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.reprocessDocumentArtifact(alloc, table_name, doc_key, artifact_name);
        const group_id = (try table_catalog.resolveGroupForKey(alloc, self.catalog, table_name, doc_key)) orelse return null;
        return try reprocessDocumentArtifactGroupLocal(ptr, alloc, group_id, table_name, doc_key, artifact_name);
    }

    fn reprocessDocumentArtifactRange(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        artifact_name: []const u8,
        req: db_mod.types.DocumentArtifactTableReprocessRequest,
    ) !?db_mod.types.DocumentArtifactTableReprocessResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.reprocessDocumentArtifactRange(alloc, table_name, artifact_name, req);
        var result = db_mod.types.DocumentArtifactTableReprocessResult{};
        errdefer result.deinit(alloc);
        var failures = std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessFailure).empty;
        var shard_cursors = std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessShardCursor).empty;
        errdefer {
            for (failures.items) |*failure| failure.deinit(alloc);
            failures.deinit(alloc);
            for (shard_cursors.items) |*cursor| cursor.deinit(alloc);
            shard_cursors.deinit(alloc);
        }

        var handled_any = false;
        if (req.shard_cursors.len > 0) {
            for (req.shard_cursors) |cursor| {
                const group_id = cursor.group_id orelse return error.InvalidArgument;
                const group_req = documentArtifactReprocessRequestForCursor(req, cursor);
                var group_result = (try reprocessDocumentArtifactRangeGroupLocal(ptr, alloc, group_id, table_name, artifact_name, group_req)) orelse continue;
                defer group_result.deinit(alloc);
                handled_any = true;
                try mergeDocumentArtifactTableReprocessResult(alloc, &result, &failures, &shard_cursors, group_id, group_result);
            }
        } else {
            const group_ids = try table_catalog.resolveGroupsForSpanEventually(
                alloc,
                self.catalog,
                table_name,
                req.from_key,
                req.to_key,
                5 * std.time.ns_per_s,
                10,
            );
            defer alloc.free(group_ids);
            if (group_ids.len == 0) return null;

            for (group_ids) |group_id| {
                var group_result = (try reprocessDocumentArtifactRangeGroupLocal(ptr, alloc, group_id, table_name, artifact_name, req)) orelse continue;
                defer group_result.deinit(alloc);
                handled_any = true;
                try mergeDocumentArtifactTableReprocessResult(alloc, &result, &failures, &shard_cursors, group_id, group_result);
            }
        }
        if (!handled_any) return null;
        result.failures = try failures.toOwnedSlice(alloc);
        result.shard_cursors = try shard_cursors.toOwnedSlice(alloc);
        return result;
    }

    fn listArtifactRepairIssues(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.ArtifactRepairListRequest,
    ) !?db_mod.types.ArtifactRepairListResult {
        const self: *ProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        if (self.localWriteOwnerSource()) |owner| return try owner.listArtifactRepairIssues(alloc, table_name, req);
        self.beginTableRequest(table_name);
        defer self.endTableRequest(table_name);

        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        const parsed_cursor = try parseArtifactRepairTableCursor(req.cursor);
        var start_index: usize = 0;
        var start_cursor: ?[]const u8 = null;
        if (parsed_cursor) |cursor| {
            while (start_index < group_ids.len and group_ids[start_index] != cursor.group_id) : (start_index += 1) {}
            if (start_index == group_ids.len) return error.InvalidArgument;
            start_cursor = cursor.local_cursor;
        }

        var result = db_mod.types.ArtifactRepairListResult{ .limit = req.limit };
        errdefer result.deinit(alloc);
        var out = std.ArrayListUnmanaged(db_mod.types.ArtifactRepairIssue).empty;
        errdefer {
            for (out.items) |*issue| issue.deinit(alloc);
            out.deinit(alloc);
        }

        var groups_scanned: usize = 0;
        for (group_ids[start_index..], start_index..) |group_id, idx| {
            if (groups_scanned >= artifact_repair_max_groups_per_request) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, null);
                break;
            }
            if (req.limit != 0 and out.items.len >= req.limit) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, null);
                break;
            }
            const remaining: u32 = if (req.limit == 0) 0 else @intCast(req.limit - @as(u32, @intCast(out.items.len)));
            var group_result = (try listArtifactRepairIssuesGroupLocal(ptr, alloc, group_id, table_name, artifactRepairListRequestForShard(
                req,
                remaining,
                if (idx == start_index) start_cursor else null,
            ))) orelse continue;
            defer group_result.deinit(alloc);
            groups_scanned += 1;
            result.groups_scanned += 1;
            result.scanned += group_result.scanned;
            try appendOwnedArtifactRepairIssues(alloc, &out, group_result.issues);
            group_result.issues = &.{};
            if (group_result.has_more) {
                result.has_more = true;
                result.next_cursor = try formatArtifactRepairTableCursorAlloc(alloc, group_id, group_result.next_cursor);
                break;
            }
        }

        result.issues = try out.toOwnedSlice(alloc);
        out = .empty;
        return result;
    }

